/* ===================== KASHVI: MAKE ANY REPORT ON REQUEST ===================== */
// "logsheet 1 to 15 october", "september ka billet stock pdf", "Q2 quarter report",
// "kal ka summary", "MIS august" -> opens the right tab, fills the dates and runs it.
const KR_REPORTS = [
  { key: "today", name: "Today's Summary (yesterday's report)", re: /(today'?s?|daily|aaj\s*ka|aaj\s*ki|din\s*ka)\s*summary|\bsummary\s*(print|pdf)/, kind: "none",
    run: async () => { await printTodaySummary(); } },
  { key: "logsheet", name: "Logsheet PDF (Prod.)", re: /log\s*-?\s*sheet|prod(uction)?\.?\s*sheet/, kind: "range", go: "reports", sub: ["subreport", "logsheet"],
    from: "logFromDate", to: "logToDate", run: async () => { await downloadLogsheetPDF(); } },
  { key: "billetstock", name: "Billet Stock Format", re: /billet\s*stock/, kind: "range", go: "reports", sub: ["subreport", "billetstock"],
    from: "stockFromDate", to: "stockToDate", run: async () => { await downloadBilletStockPDF(); } },
  { key: "stripmill", name: "Strip Mill", re: /strip\s*mill/, kind: "range", go: "reports", sub: ["subreport", "stripmill"],
    from: "stripFromDate", to: "stripToDate", run: async () => { await downloadStripMillPDF(); } },
  { key: "bisdoc", name: "BIS Doc", re: /\bbis\s*doc|\bbis\s*(report|pdf|format)/, kind: "range", go: "reports", sub: ["subreport", "bisdoc"],
    from: "bisFromDate", to: "bisToDate", run: async () => { await downloadBisDocPDF(); } },
  { key: "testcert", name: "Test Certificate (T.C.)", re: /test\s*cert|\bt\.?\s*c\.?\b(?!\s*sheet)/, kind: "range", go: "reports", sub: ["subreport", "testcert"],
    from: "tcFromDate", to: "tcToDate", run: async () => { await downloadTCPDF(); } },
  { key: "rmscrap", name: "RM / Scrap Report", re: /scrap\s*report|rm\s*\/?\s*scrap|\brm\s*report/, kind: "range", go: "reports", sub: ["subreport", "rmscrap"],
    from: "rmReportFromDate", to: "rmReportToDate", run: async () => { await downloadRMReportPDF(); } },
  { key: "slag", name: "Slag Crusher Report", re: /slag\s*crusher|slag\s*report/, kind: "range", go: "reports", sub: ["subreport", "slagcrusher"],
    from: "slagReportFromDate", to: "slagReportToDate", run: async () => { await downloadSlagReportPDF(); } },
  { key: "mis", name: "Monthly MIS", re: /\bmis\b/, kind: "month", go: "reports", sub: ["subreport", "mis"], month: "misMonth",
    run: async () => { await downloadMonthlyMisPDF(); } },
  { key: "mom", name: "Month-over-Month comparison", re: /month\s*over\s*month|\bmom\b|year\s*over\s*year/, kind: "month", go: "dashboard", sub: ["subdash", "mom"], month: "momMonth",
    run: async () => { await loadMonthOverMonth(); document.getElementById("momChartPdfBtn").click(); } },
  { key: "rmstock", needsAsk: true, name: "Raw Material Stock Report", re: /(raw\s*material|\brm\b|material)\s*stock|stock\s*report/, kind: "range", go: "stock", sub: ["substock", "rm"],
    from: "stockFromDateStock", to: "stockToDateStock", run: async () => { await loadStockReport(); if (!stockReportData) throw new Error("no stock data"); document.getElementById("stockReportPdfBtn").click(); } },
  { key: "rmdesc", name: "R.M Description", re: /r\.?\s*m\.?\s*desc|raw\s*material\s*desc/, kind: "range", go: "rmdesc",
    from: "rmDashFromDate", to: "rmDashToDate", run: async () => { await loadRawMaterialDashboard(); if (!rmDashData) throw new Error("no data"); document.getElementById("rmDashPdfBtn").click(); } },
  { key: "erp", name: "ERP Production", re: /\berp\b/, kind: "range", go: "erpprod",
    from: "erpProdFromDate", to: "erpProdToDate", run: async () => { await loadErpProduction(); if (!erpProdData) throw new Error("no data"); document.getElementById("erpProdPdfBtn").click(); } },
  { key: "outofspec", name: "Out of Spec Chemistry", re: /out\s*of\s*spec|off\s*spec|chemistry\s*(fail|out)/, kind: "range", go: "outofspec",
    from: "chemSpecFromDate", to: "chemSpecToDate", run: async () => { await loadChemSpecDashboard(); await downloadChemSpecReportPDF(); } },
  { key: "debit", name: "SI Debit Note (party-wise)", re: /debit\s*note/, kind: "range", go: "debitnote",
    from: "debitFromDate", to: "debitToDate", run: async () => { await loadDebitNoteData(); if (!debitNoteData) throw new Error("no data"); document.getElementById("debitPdfBtn").click(); } },
  { key: "inwardraw", name: "Inward Raw Data (3 PDFs)", re: /inward.*raw\s*data|raw\s*data\s*(report|pdf)/, kind: "months", go: "reports", sub: ["subreport", "simn"],
    fromM: "inwardQcFromMonth", toM: "inwardQcToMonth", run: async () => { await krClickAndWait("inwardRmRawPdfBtn"); } },
  { key: "quarter", name: "Quarter Report (PO vs Actual)", re: /quarter|po\s*vs\.?\s*actual|inward\s*qc/, kind: "months", go: "reports", sub: ["subreport", "simn"],
    fromM: "inwardQcFromMonth", toM: "inwardQcToMonth", run: async () => { await krClickAndWait("inwardQcPdfBtn"); } }
];
const KR_ASK_WORDS = /\b(report|pdf|sheet|format|summary|print|dikha|dikhao|dikhaiye|de\s*do|dedo|do|de|dijiye|bana|banao|banaiye|nikalo|nikaliye|chahiye|chaiye|open|generate|show|give|send|bhejo)\b/;

function krPdfOpen() { return !document.getElementById("pdfPreviewOverlay").classList.contains("hidden"); }
// for handlers that are not exposed as functions: click, then wait for the
// PDF preview to open or the status line to show an error
function krClickAndWait(btnId, timeoutMs = 120000) {
  return new Promise((resolve, reject) => {
    const st = document.getElementById("status");
    const before = st.textContent;
    document.getElementById(btnId).click();
    const t0 = Date.now();
    const iv = setInterval(() => {
      if (krPdfOpen()) { clearInterval(iv); resolve(); }
      else if (st.className === "err" && st.textContent !== before) { clearInterval(iv); reject(new Error(st.textContent)); }
      else if (st.className === "ok" && st.textContent !== before && !/reading|loading|preparing/i.test(st.textContent)) { clearInterval(iv); resolve(); }
      else if (Date.now() - t0 > timeoutMs) { clearInterval(iv); reject(new Error("timed out")); }
    }, 400);
  });
}
// month range ("july to september", "jul-sep 2026") and Indian FY quarters (Q1 = Apr-Jun)
function krParsePeriod(q) {
  const now = new Date(); now.setHours(0, 0, 0, 0);
  const MN = "january|february|march|april|may|june|july|august|september|sept|october|november|december|jan|feb|mar|apr|jun|jul|aug|sep|oct|nov|dec";
  // "1 to 15 october", "1-15 oct 2026", "5 se 20 september"
  const dr = new RegExp("\\b(\\d{1,2})(?:st|nd|rd|th)?\\s*(?:se|to|till|tak|-|–)\\s*(\\d{1,2})(?:st|nd|rd|th)?\\s*(" + MN + ")\\b(?:\\s*(\\d{4}|'\\d{2}))?").exec(q);
  if (dr && +dr[1] >= 1 && +dr[2] <= 31 && +dr[1] <= +dr[2]) {
    const mo = AQ_MONTHS[dr[3]];
    let y = dr[4] ? (+dr[4].replace("'", "") < 100 ? 2000 + +dr[4].replace("'", "") : +dr[4].replace("'", "")) : now.getFullYear();
    if (!dr[4] && new Date(y, mo, +dr[1]) > now) y -= 1; // start date in future -> last year
    const f = new Date(y, mo, +dr[1]), t = new Date(y, mo, +dr[2]);
    return { from: f, to: t, label: aqLabel(f, t) };
  }
  const qm = /\bq\s*([1-4])\b|\b([1-4])(st|nd|rd|th)\s*quarter\b|\bquarter\s*([1-4])\b/.exec(q);
  if (qm) {
    const n = +(qm[1] || qm[2] || qm[4]);
    const startM = [3, 6, 9, 0][n - 1];
    const yM = /\b(20\d{2})\b/.exec(q);
    let y = yM ? +yM[1] : now.getFullYear();
    if (!yM) { // pick the latest such quarter that has started
      if (new Date(y, startM, 1) > now) y -= 1;
    }
    const f = new Date(y, startM, 1); let t = new Date(y, startM + 3, 0); if (t > now) t = now;
    return { from: f, to: t, label: aqLabel(f, t) };
  }
  const mr = /\b(january|february|march|april|may|june|july|august|september|sept|october|november|december|jan|feb|mar|apr|jun|jul|aug|sep|oct|nov|dec)\b\s*(?:se|to|till|tak|-|–)\s*\b(january|february|march|april|may|june|july|august|september|sept|october|november|december|jan|feb|mar|apr|jun|jul|aug|sep|oct|nov|dec)\b(?:\s*(\d{4}|'\d{2}))?/.exec(q);
  if (mr && !/\b\d{1,2}\s*(st|nd|rd|th)?\s*(january|february|march|april|may|june|july|august|september|sept|october|november|december|jan|feb|mar|apr|jun|jul|aug|sep|oct|nov|dec)\b/.test(q)) {
    const m1 = AQ_MONTHS[mr[1]], m2 = AQ_MONTHS[mr[2]];
    let y2 = mr[3] ? (+mr[3].replace("'", "") < 100 ? 2000 + +mr[3].replace("'", "") : +mr[3].replace("'", "")) : now.getFullYear();
    if (!mr[3] && new Date(y2, m2, 1) > now) y2 -= 1;
    const y1 = m1 <= m2 ? y2 : y2 - 1;
    const f = new Date(y1, m1, 1); let t = new Date(y2, m2 + 1, 0); if (t > now) t = now;
    return { from: f, to: t, label: aqLabel(f, t) };
  }
  if (/\b(this|is)\s+(year|saal)\b|\bfy\b/.test(q)) {
    const y = now.getMonth() >= 3 ? now.getFullYear() : now.getFullYear() - 1;
    const f = new Date(y, 3, 1);
    return { from: f, to: now, label: aqLabel(f, now) };
  }
  return aqParsePeriod(q);
}
const krYM = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;

async function tryReportRequest(question) {
  const q = " " + aqNormalize(String(question).replace(/[’']/g, "'")) + " ";
  if (/(kaun|kon|which|what|list|kya\s*kya).*(report)/.test(q) && !KR_REPORTS.some(r => r.re.test(q))) {
    askDataAppendMessage("I can make these reports for you - just say the name with a date or month:\n" +
      KR_REPORTS.map(r => "• " + r.name).join("\n") +
      "\n\nExamples: \"logsheet 1 to 15 october\", \"september billet stock\", \"MIS august\", \"Q2 quarter report\", \"today's summary\".", false);
    return true;
  }
  const rep = KR_REPORTS.find(r => r.re.test(q));
  if (!rep) return false;
  // "lumps stock kitna hai" is a figure question, not a report request
  if (rep.needsAsk && !KR_ASK_WORDS.test(q)) return false;
  if (!account) { askDataAppendMessage("Please sign in first - reports are read from your OneDrive Excel files.", false); return true; }
  let p = rep.kind === "none" ? null : krParsePeriod(q);
  if (rep.kind !== "none" && !p) {
    if (rep.kind === "month") { // same default as the tab: last month
      const n = new Date(); const f = new Date(n.getFullYear(), n.getMonth() - 1, 1), t = new Date(n.getFullYear(), n.getMonth(), 0);
      p = { from: f, to: t, label: aqLabel(f, t) };
    } else {
      askDataAppendMessage(`${rep.name}: which date or month? e.g. "${rep.name.split(" (")[0].toLowerCase()} 1 to 15 october" or "... september".`, false);
      return true;
    }
  }
  const what = rep.kind === "month" ? `${rep.name} - ${p.from.toLocaleString("en-GB", { month: "long", year: "numeric" })}`
    : rep.kind === "months" ? `${rep.name} - ${krYM(p.from)} to ${krYM(p.to)}`
    : p ? `${rep.name} - ${p.label}` : rep.name;
  const msg = askDataAppendMessage(`📄 Making ${what} ...`, false);
  try {
    if (rep.go) {
      if (typeof closeKashvi === "function") closeKashvi();
      goToAppPlace({ go: rep.go, sub: rep.sub });
      await new Promise(r => setTimeout(r, 350));
    }
    if (rep.kind === "range") {
      document.getElementById(rep.from).value = aqISO(p.from);
      document.getElementById(rep.to).value = aqISO(p.to);
    } else if (rep.kind === "month") {
      document.getElementById(rep.month).value = krYM(p.from);
    } else if (rep.kind === "months") {
      document.getElementById(rep.fromM).value = krYM(p.from);
      document.getElementById(rep.toM).value = krYM(p.to);
    }
    if (typeof closeKashvi === "function") closeKashvi();
    const st = document.getElementById("status");
    if (st) { st.className = ""; st.textContent = ""; } // forget any old message
    await rep.run();
    if (!krPdfOpen() && st && st.className === "err" && st.textContent) throw new Error(st.textContent);
    msg.textContent = krPdfOpen() ? `✅ ${what} is ready (PDF opened).` : `✅ ${what} - done. See the ${rep.name} tab.`;
    if (_askChatTarget === "kashviChat") kvSpeak(msg.textContent);
  } catch (e) {
    msg.textContent = `❌ Could not make ${what}: ` + (typeof shortError === "function" ? shortError(e.message) : e.message);
    if (_askChatTarget === "kashviChat") kvSpeak(msg.textContent);
    if (typeof openKashvi === "function") openKashvi();
  }
  return true;
}

async function answerAnyQuery(question) {
    askDataAppendMessage(question, true);
    try { if (await tryReportRequest(question)) return; } catch (e) { console.warn("report request failed", e); }
    const thinking = askDataAppendMessage("Looking...", false);
    let excelAnswer = null;
    try { excelAnswer = await answerExcelQuery(question); }
    catch (e) { excelAnswer = "Error: " + (typeof shortError === "function" ? shortError(e.message) : e.message); }
    thinking.remove();
    if (excelAnswer) { askDataAppendMessage(excelAnswer, false); return; } // a figure was found - no extra cards
    askAppendResults(searchApp(question), question);
}

// Floating "Ask Your Data" sticker: opens the Ask Your Data section.
// Kashvi sticker: drag it anywhere on the screen (finger or mouse). A short
// tap still opens the chat. The place is remembered on this device.
(function askFabDrag() {
  const fab = document.getElementById("askFab");
  const bubble = document.getElementById("askFabBubble");
  if (!fab) return;
  const KEY = "askFabPos";
  const clamp = (x, y) => {
    const w = fab.offsetWidth || 76, h = fab.offsetHeight || 106;
    return [Math.min(Math.max(4, x), window.innerWidth - w - 4), Math.min(Math.max(4, y), window.innerHeight - h - 4)];
  };
  const placeBubble = () => {
    if (!bubble || !fab.style.left) return;
    const r = fab.getBoundingClientRect(), bw = bubble.offsetWidth || 120;
    let bx = r.left - bw - 8;
    if (bx < 4) bx = Math.min(r.right + 8, window.innerWidth - bw - 4);
    bubble.style.left = bx + "px"; bubble.style.top = Math.max(4, r.top + 6) + "px";
    bubble.style.right = "auto"; bubble.style.bottom = "auto";
  };
  const place = (x, y) => {
    [x, y] = clamp(x, y);
    fab.style.left = x + "px"; fab.style.top = y + "px"; fab.style.right = "auto"; fab.style.bottom = "auto";
    placeBubble();
    return [x, y];
  };
  // the saved spot (set only by the user's own drag) is the single source of truth
  const saved = () => {
    try { const p = JSON.parse(localStorage.getItem(KEY) || "null"); return p && typeof p.fx === "number" ? p : null; } catch (e) { return null; }
  };
  const visible = () => fab.getClientRects().length > 0;
  const restore = () => {
    const p = saved();
    if (p && visible()) place(p.fx * window.innerWidth, p.fy * window.innerHeight);
    else if (visible()) placeBubble();
  };
  let start = null, moved = false, suppressClick = false;
  fab.addEventListener("pointerdown", e => {
    if (e.button !== undefined && e.button > 0) return;
    const r = fab.getBoundingClientRect();
    start = { px: e.clientX, py: e.clientY, x: r.left, y: r.top, id: e.pointerId };
    moved = false;
  });
  fab.addEventListener("pointermove", e => {
    if (!start || e.pointerId !== start.id) return;
    const dx = e.clientX - start.px, dy = e.clientY - start.py;
    if (!moved && Math.hypot(dx, dy) < 8) return;   // small wobble = still a tap
    if (!moved) { moved = true; fab.classList.add("dragging"); try { fab.setPointerCapture(e.pointerId); } catch (er) {} }
    e.preventDefault();
    place(start.x + dx, start.y + dy);
  });
  const end = e => {
    if (!start) return;
    if (moved) {
      fab.classList.remove("dragging");
      suppressClick = true; setTimeout(() => { suppressClick = false; }, 350);
      const r = fab.getBoundingClientRect();
      try { localStorage.setItem(KEY, JSON.stringify({ fx: r.left / window.innerWidth, fy: r.top / window.innerHeight })); } catch (er) {}
    }
    start = null; moved = false;
  };
  fab.addEventListener("pointerup", end);
  fab.addEventListener("pointercancel", end);
  // a drag must not count as a tap (capture phase runs before the open handler)
  fab.addEventListener("click", e => { if (suppressClick) { e.stopImmediatePropagation(); e.preventDefault(); } }, true);
  // keyboard / rotation / sticker hidden while Kashvi is open: never move it from where the user put it -
  // re-apply the saved spot instead of re-clamping the current (possibly hidden = 0,0) position
  window.addEventListener("resize", restore);
  // when the sticker shows again (Kashvi closed, back on Home) put it back on its saved spot; also places the bubble
  let restoreQ = 0;   // at most once per frame (body classes change many times while the app starts)
  new MutationObserver(() => { if (!restoreQ) restoreQ = requestAnimationFrame(() => { restoreQ = 0; restore(); }); }).observe(document.body, { attributes: true, attributeFilter: ["class"] });
  restore();
  setTimeout(restore, 600);
})();

(function askFabInit() {
  const fab = document.getElementById("askFab");
  const bubble = document.getElementById("askFabBubble");
  if (!fab || !bubble) return;
  const open = () => {
    bubble.classList.add("gone");
    openKashvi();
  };
  fab.addEventListener("click", open);
  bubble.addEventListener("click", open);
  let bubbleTimerStarted = false;
  // hide the sticker while a PDF preview / popup is open, or when signed out
  const sync = () => {
    const pdfOpen = !document.getElementById("pdfPreviewOverlay").classList.contains("hidden");
    // Kashvi only after sign-in, and only on the Home screen (the tile grid) - not inside menus / pages
    const sb = document.getElementById("mainSidebar");
    const onHome = !!(sb && sb.getClientRects().length && getComputedStyle(sb).visibility !== "hidden");
    const hide = pdfOpen || !account || !onHome;
    if (document.body.classList.contains("onHome") !== onHome) document.body.classList.toggle("onHome", onHome);   // used by the "+ Smsqc" chip
    document.body.classList.toggle("askFabHidden", hide);
    if (document.body.classList.contains("askFabOn") !== !hide) document.body.classList.toggle("askFabOn", !hide);
    if (!hide && !bubbleTimerStarted) { bubbleTimerStarted = true; setTimeout(() => bubble.classList.add("gone"), 6000); }
    if (!account && document.body.classList.contains("kashviOpen") && typeof closeKashvi === "function") closeKashvi();
  };
  // at most once per frame: the page changes many classes / styles while it starts (this used to run hundreds of times then)
  let syncQ = 0;
  const syncSoon = () => { if (!syncQ) syncQ = requestAnimationFrame(() => { syncQ = 0; sync(); }); };
  // only changes that can show / hide Home or the PDF preview matter (not the clock, animations, tiles …)
  const WATCH = new Set(["mainSidebar", "contentArea", "pdfPreviewOverlay", "appSection", "loginSection", "mainLayout"]);
  new MutationObserver(ms => { if (ms.some(m => m.target === document.body || WATCH.has(m.target.id) || (m.target.contains && m.target.contains(document.getElementById("mainSidebar"))))) syncSoon(); })
    .observe(document.body, { subtree: true, attributes: true, attributeFilter: ["class", "style", "hidden"] });
  sync();
})();

/* ===================== INDIAN STANDARDS TAB ===================== */
const IND_STANDARDS = [{"id": "is228", "no": "IS 228 (Parts 1 to 24)", "title": "Methods for chemical analysis of steels", "cat": "Chemical", "facts": ["Wet-chemical and instrumental methods for steel analysis, one element/method per part", "Referee method named in IS 14650 : 2023 (Cl. 7.1.1); IS 1786 and IS 10748 also allow IS 228 or any established instrumental method", "Covers C, S (incl. combustion-IR, Part 20), Mn, P, Si, Ni, Cr, Mo, Cu, W, As, N, O, H"], "scope": "Chemical analysis of billets, TMT and strip (C, Mn, Si, S, P, Cu, Cr, Ni, Mo, N ...)", "follow": "<b>Parts (testing covered):</b><table style='width:100%;font-size:12px;border-collapse:collapse;margin:4px 0'><tr><th style='text-align:left'>Part</th><th style='text-align:left'>Element — method (range)</th></tr><tr><td>1</td><td>Carbon — volumetric method (C 0.05 to 2.50 %)</td></tr><tr><td>2</td><td>Manganese — arsenite method (plain carbon & low alloy steels)</td></tr><tr><td>3</td><td>Phosphorus — alkalimetric method (Fourth Revision, 2024)</td></tr><tr><td>4</td><td>Total carbon — gravimetric method (C ≥ 0.1 %)</td></tr><tr><td>5</td><td>Nickel — dimethylglyoxime gravimetric method (Ni ≥ 0.1 %)</td></tr><tr><td>6</td><td>Chromium — persulphate oxidation method (Cr ≥ 0.1 %)</td></tr><tr><td>7</td><td>Molybdenum — alpha-benzoinoxime method, alloy steels (Mo > 1 %, no tungsten)</td></tr><tr><td>8</td><td>Silicon — gravimetric method (Si 0.05 to 5.00 %)</td></tr><tr><td>9</td><td>Sulphur — evolution method (S 0.01 to 0.25 %)</td></tr><tr><td>10</td><td>Molybdenum — thiocyanate photometric method (Mo 0.01 to 1.5 %)</td></tr><tr><td>11</td><td>Total silicon — reduced molybdosilicate spectrophotometric method (Si 0.01 to 0.05 %)</td></tr><tr><td>12</td><td>Manganese — periodate spectrophotometric method (Mn 0.01 to 5.0 %)</td></tr><tr><td>13</td><td>Arsenic</td></tr><tr><td>14</td><td>Carbon — thermal conductivity method (C 0.005 to 2.000 %)</td></tr><tr><td>15</td><td>Copper — thiosulphate iodide method (Cu 0.05 to 5 %)</td></tr><tr><td>16</td><td>Tungsten — spectrophotometric method (W 0.1 to 2 %)</td></tr><tr><td>17</td><td>Nitrogen — thermal conductivity method (N up to 0.04 %)</td></tr><tr><td>18</td><td>Oxygen — instrumental method (O 0.01 to 0.1000 %)</td></tr><tr><td>19</td><td>Nitrogen — steam distillation method (N 0.02 to 0.50 %)</td></tr><tr><td>20</td><td>Total carbon & sulphur — infrared absorption after combustion in induction furnace (routine)</td></tr><tr><td>21</td><td>Copper — spectrometric method (Cu 0.02 to 0.5 %)</td></tr><tr><td>22</td><td>Total hydrogen — thermal conductivity method (H 0.1 to 50 ppm)</td></tr><tr><td>23</td><td>Total nitrogen — optical emission spectrometer (N 0.002 to 1.0 %)</td></tr><tr><td>24</td><td>Nitrogen — inert gas fusion, thermal conductivity (N 0.001 to 0.2 %)</td></tr></table>Year of each part (other than Part 3 : 2024): <b>NOT FOUND</b>", "keywords": "Carbon — volumetric method (C 0.05 to 2.50 %) Manganese — arsenite method (plain carbon & low alloy steels) Phosphorus — alkalimetric method (Fourth Revision, 2024) Total carbon — gravimetric method (C ≥ 0.1 %) Nickel — dimethylglyoxime gravimetric method (Ni ≥ 0.1 %) Chromium — persulphate oxidation method (Cr ≥ 0.1 %) Molybdenum — alpha-benzoinoxime method, alloy steels (Mo > 1 %, no tungsten) Silicon — gravimetric method (Si 0.05 to 5.00 %) Sulphur — evolution method (S 0.01 to 0.25 %) Molybdenum — thiocyanate photometric method (Mo 0.01 to 1.5 %) Total silicon — reduced molybdosilicate spectrophotometric method (Si 0.01 to 0.05 %) Manganese — periodate spectrophotometric method (Mn 0.01 to 5.0 %) Arsenic Carbon — thermal conductivity method (C 0.005 to 2.000 %) Copper — thiosulphate iodide method (Cu 0.05 to 5 %) Tungsten — spectrophotometric method (W 0.1 to 2 %) Nitrogen — thermal conductivity method (N up to 0.04 %) Oxygen — instrumental method (O 0.01 to 0.1000 %) Nitrogen — steam distillation method (N 0.02 to 0.50 %) Total carbon & sulphur — infrared absorption after combustion in induction furnace (routine) Copper — spectrometric method (Cu 0.02 to 0.5 %) Total hydrogen — thermal conductivity method (H 0.1 to 50 ppm) Total nitrogen — optical emission spectrometer (N 0.002 to 1.0 %) Nitrogen — inert gas fusion, thermal conductivity (N 0.001 to 0.2 %)"}, {"id": "is228_1", "no": "IS 228 (Part 1) : 2025", "title": "Methods for Chemical Analysis of Steels Part 1 Determination of Carbon by Volumetric Method (for Carbon 0.05 Percent to 2.50 Percent) (Fourth Revision)", "cat": "Chemical", "facts": ["Cl. 1: volumetric method for carbon 0.05 % to 2.50 % in plain carbon, low alloy and high alloy steels.", "Cl. 3: sample cleaned with ether or acetone, dried at 100 °C ± 5 °C.", "Cl. 4: apparatus as recommended in IS 6226 (Part 1) : 1994.", "Cl. 5.2: sample mass 1 g (drillings/shavings); furnace 1 000 °C to 1 100 °C for plain carbon steel; 1 150 °C to 1 250 °C with 0.5 g tin (plus 0.5 g pure iron for high alloy) for alloy steels; oxygen 300 ml to 400 ml per minute.", "Cl. 5.3: blank with same quantity of accelerators; Cl. 5.4: Carbon % = (A − B) × F, F from Table 1 (15 °C to 45 °C, 700 to 770 mm Hg).", "Cl. 5.5: reproducibility ± 0.01 % up to 1.50 % C; ± 0.02 % above 1.50 % C.", "First published 1952; revised 1959, 1972, 1987; this fourth revision published March 2025 (Doc MTD 34 (22153)). No amendments listed in the copy.", "Rounding off as per IS 2 : 2022.", "Lab SOP / WI (SOP/WI tab): DM/QA/WI/01"], "scope": "Carbon in steel (billets, TMT, strip)", "follow": "<b>Reproducibility (Cl. 5.5)</b><table><tr><th>Carbon content</th><th>Reproducibility</th></tr><tr><td>Up to 1.50 percent</td><td>± 0.01 percent</td></tr><tr><td>Above 1.50 percent</td><td>± 0.02 percent</td></tr></table><br><b>Combustion conditions (Cl. 5.2)</b><table><tr><th>Steel</th><th>Furnace temperature</th><th>Boat withstands</th><th>Accelerator</th></tr><tr><td>Plain carbon</td><td>1 000 °C to 1 100 °C</td><td>1 150 °C</td><td>—</td></tr><tr><td>Low alloy</td><td>1 150 °C to 1 250 °C</td><td>1 250 °C</td><td>0.5 g pure tin</td></tr><tr><td>High alloy</td><td>1 150 °C to 1 250 °C</td><td>1 250 °C</td><td>0.5 g pure tin + 0.5 g pure iron (99.99 %)</td></tr></table>", "keywords": "carbon c% volumetric combustion steel"}, {"id": "is228_2", "no": "IS 228 (Part 2) : 2024", "title": "Methods for Chemical Analysis of Steels Part 2 Determination of Manganese in Plain-Carbon and Low Alloy Steels by Arsenite Method (Fourth Revision)", "cat": "Chemical", "facts": ["Cl. 1 & 5: manganese 0.1 % to 1.5 % in plain carbon and low alloy steels by arsenite method, in absence of tungsten.", "Cl. 4: analytical grade reagents and distilled water (IS 1070).", "Cl. 5.1: Mn oxidized to permanganic acid by ammonium persulphate in presence of silver nitrate; titrated with sodium arsenite.", "Cl. 5.2.8: arsenite — 1.6 g arsenious oxide + 10 g sodium carbonate, made to 2 litres; adjusted so 1 ml = 0.1 % Mn for 0.2 g sample; standardized against steel of known Mn.", "Cl. 5.3: sample mass 0.2 g in 250 ml conical flask.", "Cl. 6.1: Mn % = (A × B / C) × 100; Cl. 6.2 reproducibility ± 0.01 / ± 0.02 / ± 0.03 %.", "Photometric Mn up to 5 % is in IS 228 (Part 12).", "First published 1952; revised 1959, 1972, 1987; this fourth revision published October 2024 (Doc MTD 34 (21371)). No amendments listed in the copy.", "Rounding off as per IS 2 : 2022.", "Lab SOP / WI (SOP/WI tab): DM/QA/WI/02"], "scope": "Manganese in steel (billets, TMT, strip)", "follow": "<b>Reproducibility (Cl. 6.2)</b><table><tr><th>Manganese content</th><th>Reproducibility</th></tr><tr><td>Below 0.06 percent</td><td>± 0.01 percent</td></tr><tr><td>0.06 percent to 1 percent</td><td>± 0.02 percent</td></tr><tr><td>Above 1 percent</td><td>± 0.03 percent</td></tr></table><br><b>Reagents (Cl. 5.2)</b><table><tr><th>Reagent</th><th>Strength</th></tr><tr><td>Dilute nitric acid</td><td>1 : 2 (v/v)</td></tr><tr><td>Phosphoric acid</td><td>85 percent</td></tr><tr><td>Dilute sulphuric acid</td><td>1 : 4 (v/v)</td></tr><tr><td>Concentrated nitric acid</td><td>rd 1.42 (IS 264)</td></tr><tr><td>Ammonium persulphate</td><td>10 percent (m/v), freshly prepared</td></tr><tr><td>Silver nitrate</td><td>1 percent (m/v)</td></tr><tr><td>Sodium chloride</td><td>1 percent (m/v)</td></tr></table>", "keywords": "manganese mn% arsenite steel"}, {"id": "is228_3", "no": "IS 228 (Part 3) : 2024", "title": "Methods for Chemical Analysis of Steels - Part 3 Determination of Phosphorus by Alkalimetric Method (Fourth Revision)", "cat": "Chemical", "facts": ["Cl. 1: Covers determination of phosphorus content of plain carbon steel and alloy steels by alkalimetric method; no concentration range stated.", "Cl. 5: Phosphorus precipitated as ammonium phosphomolybdate, dissolved in known excess of standard NaOH, excess titrated with standard nitric acid (0.1 N).", "Cl. 6 / 7: Sample mass 2 g for all steel types (plain carbon/low alloy without V; stainless/high Cr; high Si/Ti/Zr; Cr-V; high speed/W; austenitic Mn; high As up to 0.1 percent).", "Cl. 6.3 Note: acidity before phosphomolybdate precipitation to be maintained at 5 to 10 percent.", "Cl. 8: Blank determination with same quantity of all reagents.", "Cl. 9.1: P, percent = [(B - A) × C / D] × 100.", "Cl. 9.2: Reproducibility ± 0.001 5 percent.", "First published 1952, revised 1959, 1972, 1987; fourth revision October 2024 (Doc MTD 34 (21384)). No amendments listed in the copy.", "Rounding off as per IS 2 : 2022.", "Lab SOP / WI (SOP/WI tab): DM/QA/WI/03"], "scope": "Phosphorus in steel", "follow": "<table><tr><th>Steel type</th><th>Clause</th><th>Sample mass</th></tr><tr><td>Plain carbon and low alloy steel without vanadium</td><td>6</td><td>2 g</td></tr><tr><td>Stainless, high Cr, Ni-Cr and similar alloy steel without W or V</td><td>7.1</td><td>2 g</td></tr><tr><td>High silicon, titanium or zirconium steel</td><td>7.2</td><td>2 g</td></tr><tr><td>Cr-V steels / steels with V but no W</td><td>7.3</td><td>2 g</td></tr><tr><td>High speed steels / steels with W, with or without V</td><td>7.4</td><td>2 g</td></tr><tr><td>Austenitic manganese steels</td><td>7.5</td><td>2 g</td></tr><tr><td>Steels containing high arsenic up to 0.1 percent</td><td>7.6</td><td>2 g</td></tr></table><br><b>Reproducibility (9.2):</b> ± 0.001 5 percent", "keywords": "phosphorus p% alkalimetric steel"}, {"id": "is228_8", "no": "IS 228 (Part 8) : 1989", "title": "Methods for Chemical Analysis of Steels - Part 8 Determination of Silicon by the Gravimetric Method (for Silicon 0.05 to 5.00 Percent) (Third Revision)", "cat": "Chemical", "facts": ["Cl. 1.1: Gravimetric method for silicon 0.05 to 5.00 percent in plain carbon and alloy steels including high speed steels containing tungsten.", "Cl. 4.1: Silicic acid dehydrated by fuming with sulphuric acid; silica ignited, weighed, volatilized with HF; loss in mass represents silica.", "Cl. 4.3.1: Sample mass 5.0 g (Si up to 0.1 percent), 2.5 g (up to 1 percent), 1 g (up to 5 percent); ignition at 1 050 °C.", "Cl. 4.3.2 / 4.3.3 / 4.3.4: High Cr steel 1 g; high speed (W) steel 2 g, reignition at 750 °C; high Si steel 1 g.", "Cl. 4.4: Si, percent by mass = (A - B) × 46.75 / C.", "Cl. 4.5: Reproducibility ± 0.02 at 0.5 percent, ± 0.05 at 2.0 percent, ± 0.07 at 4.0 percent level.", "Adopted 24 November 1989; Third Reprint August 1997; Reaffirmed 2004, 2014, 2019, 2023. No amendments listed in the copy.", "Rounding off as per IS 2 : 1960.", "Lab SOP / WI (SOP/WI tab): DM/QA/WI/04"], "scope": "Silicon in steel", "follow": "<table><tr><th>Silicon content</th><th>Sample mass (plain carbon steel, 4.3.1)</th></tr><tr><td>Up to 0.1 percent</td><td>5.0 g</td></tr><tr><td>Up to 1 percent</td><td>2.5 g</td></tr><tr><td>Up to 5 percent</td><td>1 g</td></tr></table><br><table><tr><th>Level</th><th>Reproducibility (4.5)</th></tr><tr><td>0.5 percent</td><td>± 0.02</td></tr><tr><td>2.0 percent</td><td>± 0.05</td></tr><tr><td>4.0 percent</td><td>± 0.07</td></tr></table>", "keywords": "silicon si% gravimetric steel"}, {"id": "is228_6", "no": "IS 228 (Part 6) : 2024", "title": "Methods for Chemical Analysis of Steels Part 6 Determination of Chromium by Persulphate Oxidation Method (for Chromium ≥ 0.1 Percent) (Fourth Revision)", "cat": "Chemical", "facts": ["Cl. 1: chromium ≥ 0.1 % in low alloy and high alloy steels; not applicable to steels containing tungsten.", "Cl. 4: analytical grade reagents and distilled water (IS 1070).", "Cl. 5.1: dissolve in H3PO4–H2SO4 mixture + HNO3; Cr, Mn (and V) oxidized by ammonium persulphate with AgNO3 catalyst; permanganic acid destroyed with dilute HCl; Cr reduced by ferrous ammonium sulphate, excess back titrated with KMnO4.", "Cl. 5.3.1: sample 2 g (Cr < 2 %), 0.2 g to 0.5 g for high alloy steels; 50 ml acid mixture; dilute to 300 ml with hot water.", "Cl. 5.3.2: 20 ml AgNO3 (0.5 %) + 20 ml ammonium persulphate (15 g/100 ml), boil 8 min to 10 min at 300 ml.", "Cl. 5.3.3–5.3.5: FAS excess at least 5 ml; back titration to pink lasting 30 s to 40 s; vanadium and dilution/colour corrections.", "Cl. 5.4.1: Cr % = (A × B − C) × D × 0.017 33 × 100 / E.", "Cl. 5.2.8: KMnO4 ≈ 0.1 N standardized with 0.134 g sodium oxalate at 70 °C; 1 ml 0.1 N = 0.006 7 g sodium oxalate.", "First published 1952; revised 1959, 1974, 1987; this fourth revision published November 2024. No amendments listed in the copy.", "Rounding off as per IS 2 : 2022.", "Lab SOP / WI (SOP/WI tab): DM/QA/WI/09"], "scope": "Chromium in alloy steel (billets, TMT, strip)", "follow": "<b>Reproducibility (Cl. 5.4.2)</b><table><tr><th>Chromium content</th><th>Reproducibility</th></tr><tr><td>0.1 to 0.5 percent</td><td>± 0.025 percent</td></tr><tr><td>0.5 to 1 percent</td><td>± 0.036 percent</td></tr><tr><td>1 to 5 percent</td><td>± 0.120 percent</td></tr><tr><td>5 percent and above</td><td>± 0.20 percent</td></tr></table><br><b>Reagents (Cl. 5.2)</b><table><tr><th>Reagent</th><th>Strength</th></tr><tr><td>Phosphoric acid – sulphuric acid mixture</td><td>165 ml H2SO4 + 132 ml H3PO4 per litre</td></tr><tr><td>Concentrated nitric acid</td><td>rd 1.42 (IS 264)</td></tr><tr><td>Silver nitrate</td><td>0.5 percent (m/v)</td></tr><tr><td>Ammonium persulphate</td><td>15 g in 100 ml, freshly prepared</td></tr><tr><td>Potassium permanganate</td><td>1 percent (m/v)</td></tr><tr><td>Dilute hydrochloric acid</td><td>1 : 3 (v/v)</td></tr><tr><td>Ferrous ammonium sulphate</td><td>≈ 0.1 N (40 g/l in 5 % H2SO4)</td></tr><tr><td>Standard potassium permanganate</td><td>≈ 0.1 N (3.2 g/l)</td></tr></table>", "keywords": "chromium cr% persulphate steel ferrous ammonium sulphate permanganate"}, {"id": "is1527", "no": "IS 1527 : 1972", "title": "Methods for Chemical Analysis of High Silica Refractory Materials (First Revision)", "cat": "Refractory", "facts": ["Adopted 25 October 1972; earlier published 1960; reaffirmed 1996, 2011, 2017, 2022 (Fourth Reprint January 1999).", "1.1 Scope: LOI and oxides of Si, Al, Fe, Ti, Ca, Mg and alkali metals in high silica materials (over 94 percent SiO2); usable for materials with silica not less than 90 percent.", "0.2 Methods may be used as referee methods and for routine analysis.", "2.1 Sampling as per IS : 1528-1962. 2.2 Laboratory sample: 20 g after quartering, magnet, agate mortar, through IS Sieve 15 (aperture 149 microns). 2.3 Test sample dried at 105 to 110 °C.", "4 LOI: 1 g, platinum crucible, muffle 950 to 1 000 °C, about 30 min; LOI % = A/B × 100.", "5 Silica (gravimetric): about 0.5 g fused with 3 g Na2CO3 in 100-ml Pt dish; HCl dehydration, bake 1 h at 105 to 110 °C; No. 42 paper; ignite at 1 050 °C; HF + H2SO4 volatilization; residual silica in solution S (500 ml) by molybdenum blue at 810 nm; SiO2 % = [(B − C) + D]/A × 100.", "6 Alumina by EDTA (zinc back-titration, xylenol orange, NH4F release); 7 Iron by o-phenanthroline at 510 nm; 8 Titania by H2O2 at 410 nm; 9 CaO and MgO by EDTA; 10 Alkalis by flame photometer.", "Cited by IS 10047 : 2023, 5.2 for chemical analysis of alumino-silicate ramming mass/plastics.", "Lab SOP / WI (SOP/WI tab): DM/QA/WI/36"], "scope": "Ramming mass — silica (SiO2) test", "follow": null, "keywords": "silica sio2 ramming mass refractory"}, {"id": "is10047", "no": "IS 10047 : 2023", "title": "Refractory Plastic and Ramming Mass — Method of Test (First Revision)", "cat": "Refractory", "facts": ["Published August 2023; MTD 15; first published 1981. Assistance derived from ISO 1927-5 : 2012.", "1.1 Prescribes methods of sampling and tests of refractory plastic and ramming mass; 1.2 does not cover dry vibratable masses (3.4: unshaped refractory placed in the dry state by vibration or ramming).", "4.1 Lot: same type and grade, same manufacturer, similar production conditions; maximum lot mass 50 tonnes.", "4.2 Sample size: minimum about 50 kg; 50 kg bags selected at random as per Table 1 (up to 10 t: 1; 10 t to 25 t: 2; over 25 t up to 50 t: 4).", "4.3 Tests: PCE, apparent porosity, bulk density, PLC, CCS, thermal conductivity, HMOR, and chemical analysis.", "5.1 Chemical analysis on loss free basis by grinding 50 mm × 50 mm cylinder (clause 7) to 104 microns (gravimetric) or 45 microns (instrumental).", "5.2 Chemical analysis: alumino-silicate — IS 1527 and IS 12107 (Part 1); basic — IS 1760 (Part 2) or IS 12667 (Part 1); chrome containing — IS 12667 (Part 1). Instrumental analysis alternatively as agreed; gravimetric is referee in dispute.", "6 PCE: cone from 50 mm × 50 mm cylinder (clause 7), test as per IS 1528 (Part 1).", "7 Specimen preparation (50 mm × 50 mm cylinder): sand rammer (50 mm stamp head, 6.4 kg weight, 50 mm drop), 10 + 10 impacts, height 50 mm ± 2 mm; 7.2.1 dry ramming mass reduced to 50 kg by coning and quartering, divided into five test samples; Table 2 material requirement (98.175 cm<sup>3</sup>; 216 g to 265 g for BD 2.20 to 2.70).", "8 Workability index = (initial height − final height)/initial height × 100 (3 impacts).", "9 Firing: 100 °C/h to test temperature, 6 h soak, ± 10 °C.", "10 Bulk density: dry 110 °C for 24 h; geometric as per IS 1528 (Part 12), or IS 1528 (Part 15) if specimen withstands water; BD = W/V.", "11 Apparent porosity: IS 1528 (Part 15). 12 CCS: IS 1528 (Part 4), minimum four specimens. 13 PLC: IS 1528 (Part 6). 14 Thermal conductivity: IS 17107 (pre-fired at 1 000 °C). 15 HMOR: (25 ± 1) mm × (25 ± 1) mm × approx. 150 mm, IS 1528 (Part 20).", "Determination of moisture has been withdrawn in this revision (Foreword f).", "7.4 All test specimens shall meet the corresponding requirements for acceptance of the lot.", "Agreement clauses: 4.2, 5.1, 5.2, 6.1, 7.3, 9.1, 11.2, 13.2 and 15.1. Rounding off as per IS 2 : 2022.", "Lab SOP / WI (SOP/WI tab): DM/QA/SOP/03"], "scope": "Ramming mass — full testing (chemical + physical)", "follow": "<b>Table 1 Numbers of Bags/Containers to be Selected for Different Lots (Clauses 4.2 and 7.3)</b><table><tr><th>Sl No.</th><th>Lot Weight</th><th>No. of 50 Kg Containers/Bags to be Selected as Samples</th></tr><tr><td>i)</td><td>Up to 10 tonnes</td><td>1</td></tr><tr><td>ii)</td><td>10 tonnes to 25 tonnes</td><td>2</td></tr><tr><td>iii)</td><td>Over 25 tonnes up to 50 tonnes</td><td>4</td></tr></table><br><b>Table 2 Material Requirement for Different Densities (Clauses 7.5.2.3 and 7.5.2.5)</b><table><tr><th>Shape</th><th>Dimensions</th><th>Volume cm3</th><th>2.20</th><th>2.30</th><th>2.40</th><th>2.50</th><th>2.60</th><th>2.70</th></tr><tr><td>Cylinder</td><td>50 mm × 50 mm</td><td>98.175</td><td>216</td><td>226</td><td>236</td><td>246</td><td>256</td><td>265</td></tr></table>(Weight in grams of the test piece according to the bulk density, g/cm3; guidance only.)", "keywords": "sampling ramming mass refractory bags lot"}, {"id": "is12107", "no": "IS 12107 (Part 1) : 1987", "title": "Methods of Chemical Analysis of Alumino Silicate Refractory Materials: Part 1 Determination of Loss on Ignition", "cat": "Refractory", "facts": ["Adopted 24 August 1987 (First Reprint May 1989); latest reaffirmation seen in copy: 2022.", "1 Scope: determination of loss on ignition in alumino silicate refractory materials.", "2.1 Sampling as per IS : 1528 (Part 7)-1974. 2.2 Laboratory sample: 20 g after quartering, magnet, agate mortar, through IS Sieve 15 (aperture 75 µm). 2.3 Test sample dried at 105 to 110 °C.", "3 Analytical grade reagents and distilled water (applies to all parts).", "5.2 Procedure: 1.00 g in weighed platinum crucible, muffle furnace slowly raised to 1 025 ± 20 °C, ignite 1 hour, cool in desiccator (preferably magnesium perchlorate), repeat to constant weight.", "5.3 LOI = (A − B)/C × 100 (A = crucible + sample, B = crucible + residue, C = sample mass, g).", "Other parts: Part 2 silica, 3 aluminium, 4 phosphorus, 5 titanium, 6 iron, 7 manganese, 8 calcium and magnesium, 9 sodium and potassium.", "Cited by IS 10047 : 2023, 5.2.", "Lab SOP / WI (SOP/WI tab): DM/QA/WI/37"], "scope": "Ramming mass — Loss on Ignition (LOI)", "follow": null, "keywords": "loi loss on ignition ramming mass refractory"}, {"id": "is12107_3", "no": "IS 12107 (Part 3) : 1987", "title": "Methods of Chemical Analysis of Alumino Silicate Refractory Materials: Part 3 Determination of Aluminium", "cat": "Refractory", "facts": ["Adopted 24 August 1987 (© April 1988); latest reaffirmation seen in copy: 2022.", "1 Scope: determination of aluminium (as Al2O3) in alumino silicate refractory materials.", "2 EDTA method: Al (and Fe, Ti) complexed with excess 0.025 M EDTA by boiling; excess back titrated with 0.025 M zinc acetate at pH 5.3 (xylenol orange); NaF (1 g) liberates EDTA from Al/Ti complex, titrated with zinc acetate (V).", "2.3.1 Aliquot: 25 ml of main solution from IS 12107 (Part 2), 2.3.3 (silica determination); 35 ml EDTA, 15 ml + 5 ml buffer pH 5.3, boil 5 min twice.", "2.2.6.1 Standard Al solution: 0.674 5 g Al foil / 1 000 ml (1 ml = 0.001 275 g Al2O3).", "2.3.2 Al2O3 % = V × E × 500 × 100 / (25 × M) − 0.673 8 × T (T = % TiO2 from IS 12107 (Part 5)).", "Use for remix / redex (aluminium dross) is a laboratory adaptation outside the IS scope; validation required (ISO/IEC 17025 : 2017, 7.2.2.1). Result = total Al as Al2O3; metallic Al not separated.", "Other parts: 1 LOI, 2 silica, 4 phosphorus, 5 titanium, 6 iron, 7 manganese, 8 calcium and magnesium, 9 sodium and potassium.", "Lab SOP / WI (SOP/WI tab): DM/QA/WI/50"], "scope": "Total aluminium (as Al2O3) — remix / redex powder (adapted), alumino-silicate refractories", "follow": null, "keywords": "remix redex aluminium dross al2o3 alumina total aluminium deoxidiser powder"}, {"id": "iso21078", "no": "ISO 21078-1 : 2008", "title": "Determination of boron(III) oxide in refractory products — Part 1: Determination of total boron(III) oxide in oxidic materials for ceramics, glass and glazes", "cat": "Refractory", "facts": ["First edition 2008-01-15; ISO/TC 33 with CEN/TC 187. Copy available is the French-language (F) preview, up to clause 7.5 (clauses 8 to 11 and Annex A not in copy).", "1 Scope: B2O3 in refractory products and raw materials at 0.01 % and above; total B2O3 in oxidic materials.", "1 Methods: a) alkaline titrimetry > 0.5 %; b) azomethine H 0.01 % to 2.5 %; c) curcumin (rosocyanine) 0.01 % to 1.0 %; d) ICP-AES 0.01 % to 15 % (up to 30 % with modified oxide fluxes).", "4.3 Dry unshaped refractory: one bag or 5 kg from a lot, reduce to about 100 g, pass 300 µm; 4.5 about 25 g ground to pass 106 µm, dried 110 °C ± 5 °C for at least 2 h.", "5 Duplicate determinations simultaneously, with reagent blank.", "6 Alkaline titrimetry: 1.00 g sample fused with NaOH at about 600 °C; interfering ions precipitated with 1.5 g CaCO3 (twice); pH 6.5, 20 g D(−)-mannitol, titrate with NaOH to pH 6.8.", "6.2.8 F = 0.01 / V (standardization on 100 ml of 0.1 mg/ml B2O3 standard with 10 g mannitol); 6.7 wB1 % = (V1 − V2) × F / m × 100.", "Annex A (informative): interlaboratory test results (not in available copy).", "Boric acid (H3BO3) % = B2O3 % × 1.776 (stoichiometric; not from ISO 21078-1).", "Lab SOP / WI (SOP/WI tab): DM/QA/WI/38"], "scope": "B2O3 / boric acid in ramming mass", "follow": null, "keywords": "b2o3 boron oxide boric acid ramming mass mannitol"}, {"id": "is1528_7", "no": "IS 1528 (Part 7) : 2010", "title": "Methods of Sampling and Physical Tests for Refractory Materials: Part 7 Methods of Sampling and Criteria for Conformity (Second Revision)", "cat": "Refractory", "facts": ["Scope (1): methods of sampling and criteria for conformity for refractory raw materials, finished shaped refractories, mortars and monolithics (excluding refractory castables).", "Second Revision (first published 1962, revised 1974); Refractories Sectional Committee MTD 15; reaffirmed 2015 and 2020.", "Terminology as per IS 4041 (3); random sampling methods as per IS 4905 (4.6.2.1); control charts as per IS 397 (Part 0) (4.2).", "4.4.1: raw-material mixture sample of about 15 kg — from stacks after souring (3 parts × 5 points × about 1 kg), from extruders (5 equally spaced intervals) or from mixtures (dry process, increments at hopper).", "4.5.1: lot of refractory mortar/monolithics = same type and grade, same firm, similar production conditions; maximum 50 tonnes.", "4.5.2: three containers/bags at random per lot; about 1 kg from each after thorough mixing and coning and quartering, for PCE, moisture content, sieve analysis and chemical analysis (lot of less than three containers: 1 kg from each).", "4.6.2.1 / Table 1: sample size and permissible defectives for shaped bricks (lots 300 to 22 000); palletized/cardboard packed: 5 percent pallets/boxes.", "4.6.2.2: number of samples per test — PCE 2, RUL 1, spalling 3, CCS 5, MOR 5, PLC 5, AP 5, true sp. gr./true density 3, BD 5, CO resistance 2, chemical 1 (composite).", "5.2.1: conformity for apparent porosity and CCS as agreed between purchaser and manufacturer.", "5.2.2: true sp. gr., true density, BD — all results satisfactory, or one result off by not more than 0.01 and average within the limit.", "5.2.3: PLC — five samples; one result not more than 10 percent of specified maximum allowed if average is within maximum limit.", "5.2.4 PCE (two results); 5.2.5 chemical as per IS 12107, IS 1527, IS 1760 (Parts 1 to 6), IS 12667 (XRF if agreed); 5.2.8 sieve analysis; 5.2.9 rounding as per IS 2; 5.2.10 retest only for the failed property if mutually agreed.", "Amendment No. 1 (December 2022), 5.2.11: MOR — average of all results satisfies the requirement and individual results not to vary more than 20 percent (with reference to the highest obtained value).", "Amendment No. 1 (December 2022), 5.2.12: conformity criteria of all other tests not specified in 4.6.2.2 as agreed between purchaser and manufacturer.", "Lab SOP / WI (SOP/WI tab): DM/QA/SOP/03"], "scope": "Sampling & conformity of refractories (ramming mass)", "follow": "<b>4.5 Sampling of Refractory Mortar and Monolithics</b><ul><li>4.5.1 Lot: containers/bags of same type and grade, same firm, similar conditions of production; maximum weight of any lot 50 tonnes.</li><li>4.5.2 Three containers/bags selected at random over the whole lot; about 1 kg from each after thorough mixing and coning and quartering, for PCE, moisture content, sieve analysis and chemical analysis. Lot of less than three containers: 1 kg from each container.</li></ul><b>4.6.2.2 Number of samples for physical and chemical tests</b><table><tr><th>Characteristic</th><th>Number of Samples to be Tested</th><th>Refractories Required</th></tr><tr><td>Pyrometric cone equivalent</td><td>2</td><td>1 kg material from portions of bricks left over from other tests (see Note 2)</td></tr><tr><td>Refractoriness under load</td><td>1</td><td>2 (one for retest)</td></tr><tr><td>Spalling resistance</td><td>3</td><td>3 or portions of bricks left over from other tests (see Note 2)</td></tr><tr><td>Cold crushing strength</td><td>5</td><td>5</td></tr><tr><td>Modulus of rupture</td><td>5</td><td>5</td></tr><tr><td>Permanent linear change after reheating</td><td>5</td><td>5</td></tr><tr><td>Apparent porosity</td><td>5</td><td>5 or portions of bricks left over from other tests (see Note 2)</td></tr><tr><td>True specific gravity and true density</td><td>3</td><td>3 or portions of bricks left over from other tests (see Note 2)</td></tr><tr><td>Bulk density</td><td>5</td><td>5</td></tr><tr><td>Resistance to carbon monoxide</td><td>2</td><td>2</td></tr><tr><td>Chemical analysis</td><td>1</td><td>A composite sample from portions of bricks left over from other tests (see Note 2)</td></tr></table><br><b>Table 1 Size of Sample and Permissible Number of Defective Pieces (Clauses 4.6.2.1 and 5.2)</b><table><tr><th>Sl No.</th><th>Lot Size</th><th>Sample Size</th><th>Permissible Number of Defective Pieces: General Requirement</th><th>Permissible Number of Defective Pieces: Tolerance on Size or Shaped Bricks</th></tr><tr><td>i)</td><td>300 – 500</td><td>30</td><td>5</td><td>1</td></tr><tr><td>ii)</td><td>501 – 800</td><td>40</td><td>6</td><td>1</td></tr><tr><td>iii)</td><td>801 – 1 300</td><td>55</td><td>8</td><td>2</td></tr><tr><td>iv)</td><td>1 301 – 3 200</td><td>75</td><td>10</td><td>2</td></tr><tr><td>v)</td><td>3 201 – 8 000</td><td>115</td><td>14</td><td>3</td></tr><tr><td>vi)</td><td>8 001 – 22 000</td><td>150</td><td>18</td><td>4</td></tr></table>NOTES: 1 Above 22 000 numbers not exceeding another 22 000 will form a separate lot. 2 General requirement, iron spots, warpage, cracks, chipping, lamination, etc. For lots of size less than 300, the size of the sample and the corresponding criteria for conformity shall be as agreed to between the purchaser and the supplier.", "keywords": "sampling ramming mass refractory bags lot"}, {"id": "is1470", "no": "IS 1470 : 2025", "title": "Silicomanganese — Specification (Fifth Revision)", "cat": "Raw material", "facts": ["Fifth Revision, October 2025 (first published 1960; revised 1969, 1979, 1990 and 2013); Ferroalloys Sectional Committee MTD 05.", "Cl. 3.1: silicomanganese — Mn 50 to 75 percent and Si 10 to 35 percent by mass; low carbon up to 0.1 percent C, medium carbon up to 1.0 percent, high carbon up to 3.0 percent (3.1.1 to 3.1.3).", "Cl. 3.3: consignment by tapped lot, graded lot (melts not differing by more than 3 percent) or blended lot (crushed below 50 mm and mixed).", "Cl. 7.2.4: recommended residual elements B 0.03 percent Max, Ti 0.25 percent Max, Al 0.25 percent Max.", "Cl. 7.2.5: analysis by IS 1559 or any established instrumental/chemical method; IS 1559 is referee method in dispute.", "Cl. 8.2: size analysis per IS 1607; sieves per IS 460 (Part 1) and (Part 2), checked periodically per IS 460 (Part 3) with correction factor applied; undersize/oversize valid at point of delivery.", "Cl. 10: sampling per IS 1472 for chemical analysis and IS 15765 for sieve analysis and size determination.", "Cl. 12.1 marking: source of manufacture, grade designation, constitution of consignment, size range, quantity, lot/consignment number; 12.2 BIS Standard Mark.", "Cl. 9: reasonably free from slag and non-metallic inclusions; slag and anti-burning materials by mutual agreement."], "scope": "Inward Silico Manganese — Mn, Si, C, P, S and size checks", "follow": "<b>Table 1 Chemical Composition of Silicomanganese</b> (Clauses 4, 7.2.1, 7.2.2 and 7.2.3)<table><tr><th>Sl No.</th><th>Grade Designation (as per IS 2085)</th><th>Mn</th><th>Si Min</th><th>C Max</th><th>P Max</th><th>S Max</th></tr><tr><td>i)</td><td><b>High carbon</b></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td>a) Si16Mn73</td><td>70 to 75</td><td>16</td><td>2.20</td><td>0.30</td><td>0.03</td></tr><tr><td></td><td>b) Si16Mn68</td><td>65 to 70</td><td>16</td><td>2.20</td><td>0.30</td><td>0.03</td></tr><tr><td></td><td>c) Si15Mn63</td><td>60 to 65</td><td>15</td><td>2.50</td><td>0.30</td><td>0.03</td></tr><tr><td>ii)</td><td><b>Medium carbon</b></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td>a) Si20Mn56</td><td>52 to 58</td><td>20</td><td>1.00</td><td>0.30</td><td>0.03</td></tr><tr><td>iii)</td><td><b>Low carbon</b></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td></td><td>a) Si24Mn53</td><td>50 to 55</td><td>24</td><td>0.10</td><td>0.30</td><td>0.03</td></tr></table>Notes: 1 Aluminium content shall be 0.5 percent, Max when produced by alumino thermic process. 2 If agreed upon between manufacturer and purchaser, P-0.35 percent, Max and S-0.05 percent, Max can be permitted. 3 Remainder element in all the grades mentioned above is Fe.<br><b>Table 2 Particle Size Range</b> (Clause 8.1)<table><tr><th>Sl No.</th><th>Size Designation</th><th>Size Range up to and above Including, mm</th><th>Undersize, Percent by Mass, Max</th><th>Oversize Percent by Mass, Max</th></tr><tr><td>i)</td><td>I</td><td>10 to 125</td><td>10</td><td>10</td></tr><tr><td>ii)</td><td>II</td><td>3.15 to 10</td><td>10</td><td>10</td></tr><tr><td>iii)</td><td>II</td><td>Up to 3.15</td><td>—</td><td>10</td></tr></table>Notes: 1 For oversize, no piece to exceed 1.15 times the maximum limit of the size range specified in two or three directions. 2 In the undersized material, fraction below 3.15 mm shall not exceed 5 percent. If exceeds, this shall be agreed upon between the supplier and the purchaser.<br><ul><li>Sampling: cl. 10 — IS 1472 (chemical), IS 15765 (sieve analysis/size)</li><li>Testing: cl. 7.2.5 — IS 1559 (referee); size analysis cl. 8.2 — IS 1607, sieves IS 460 (Parts 1, 2, 3)</li><li>Marking: cl. 12.1 (a) to (f); BIS Standard Mark cl. 12.2</li></ul>", "keywords": ""}, {"id": "is1253", "no": "IS 1253 : 1992", "title": "Aluminium for Use in Iron and Steel Manufacture — Specification (Third Revision)", "cat": "Raw material", "facts": ["Reaffirmed 2005 to 2012, 2017 and 2022 (cover of copy). First published 1958, revised 1965 and 1980; third revision December 1992 (Doc MTD 7 (3542)). No amendments listed in the copy.", "Cl. 1: Aluminium in the form of shot, notch bar and any other shape suitable for use in the manufacture of iron and steel. Cl. 3: supply per IS 10259 : 1982.", "Cl. 4: Grade 1 (normally for mild steel and low alloy steels) and Grade 2 (normally for alloy steels and special steels); earlier Grades 1930 and 1970 redesignated (Foreword).", "Cl. 5: Uniform quality, free from dross, slag and other harmful contamination; surface free from heavy oxidized layer.", "Cl. 6.2: Analysis as per IS 504 : 1963 or any other instrumental/chemical method; IS 504 is the referee method in case of dispute (current edition IS 504 (Parts 1 to 12) : 2002 — DM/QA/WI/40 to 34).", "Cl. 7: Shot pea-size approximately 5 to 10 mm diameter; notched bar shape and size as in IS 1820 : 1979; any other suitable shape.", "Cl. 8: One sample for each cast or every 1 000 kg or part thereof; drawn and prepared per IS 1817 : 1961; shot sample melted and chill cast as bar about 6 mm thick (DM/QA/SOP/04).", "Cl. 9: Marking — cast/lot number, grade, source of manufacture; Standard Mark optional. Cl. 10: test certificate with cast/lot number, grade and chemical composition for each consignment.", "Rounding off per IS 2 : 1960; significant places same as specified value (Foreword).", "Lab SOP / WI (SOP/WI tab): DM/QA/SOP/04, DM/QA/WI/40, DM/QA/WI/41, DM/QA/WI/42, DM/QA/WI/43, DM/QA/WI/44, DM/QA/WI/45, DM/QA/WI/46"], "scope": "Aluminium shot / notch bar / wire for deoxidation — grade, chemistry, sampling", "follow": "<b>Table 1 Chemical Composition (Clause 6.1)</b><table><tr><th>Constituent</th><th>Grade 1 Percent</th><th>Grade 2 Percent</th></tr><tr><td>Aluminium, Min</td><td>93.0</td><td>97.0</td></tr><tr><td><b>Impurities</b></td><td></td><td></td></tr><tr><td>Copper, Max</td><td>4.5</td><td>2.0</td></tr><tr><td>Zinc, Max</td><td>1.0</td><td>0.5</td></tr><tr><td>Magnesium, Max</td><td>1.0</td><td>0.5</td></tr><tr><td>Tin, Max</td><td>—</td><td>0.2</td></tr><tr><td>Arsenic, Max</td><td>—</td><td>0.2</td></tr><tr><td>Bismuth, Max</td><td>—</td><td>0.2</td></tr><tr><td>Total of copper, zinc, magnesium, silicon and iron, Max</td><td>7.0</td><td>—</td></tr><tr><td>Total of copper, zinc, magnesium, silicon, iron, tin, arsenic and bismuth, Max</td><td>—</td><td>3.0</td></tr></table><b>Sampling, marking and certificate</b><ul><li>8.1 For chemical analysis, one sample shall be taken for each cast or every 1 000 kg or part thereof, of the aluminium.</li><li>8.2 Samples shall be drawn and prepared in accordance with IS 1817 : 1961.</li><li>8.3 In case of shot, the sample shall be melted and chill cast in the shape of bar of thickness 6 mm (approximate).</li><li>9.1 Each notch bar/any other shape or the container in case of shots shall be suitably marked with: a) cast/lot number, b) grade of aluminium, and c) indication of the source of manufacture.</li><li>9.2 Each notch bar/any other shape or the container in case of shots may also be marked with the Standard Mark.</li><li>10 Each consignment shall be supplied along with a certificate giving the cast/lot number, grade and related chemical composition of aluminium.</li></ul>", "keywords": "sampling aluminium al shot notch bar ingot wire deoxidant aluminium al purity impurities copper zinc magnesium silicon iron tin manganese shot notch bar wire ingot"}, {"id": "is504", "no": "IS 504 (Parts 1 to 12) : 2002", "title": "Chemical Analysis of Aluminium and Its Alloys, Parts 1 to 12 (Second Revision)", "cat": "Chemical", "facts": ["Reaffirmed 2005 to 2012, 2018 and 2023 (cover of copy). First published 1954, revised 1963; second revision June 2002 (Doc MTD 28 (3887)); printed as a single publication.", "Each Part: sampling per IS 1817 (cl. 3); analytical grade reagents and reagent grade water IS 1070 (cl. 4); rounding per IS 2 : 1960 (Foreword).", "Part 1 Si: spectrophotometric (815 nm) up to 0.10 % (cl. 5); molybdenum yellow (about 400 nm) 0.02 to 0.3 % (cl. 6; scope table prints '0.02-0.03'); gravimetric over 0.3 %, factor 46.72 (cl. 7); Pb by sulphide colorimetric (cl. 8).", "Part 2 Fe: O-phenanthroline (510 nm) 0.03 to 0.10 % (cl. 5); potassium dichromate titrimetric above 0.10 %, N/55.85, 1.000 g sample (cl. 6, 7).", "Part 3 Cu: diethyl-dithiocarbamate (435 nm) up to 0.1 % (cl. 5); iodimetric over 0.1 %, 2 g sample (cl. 6; 6.4 in presence of Sb and Sn).", "Part 4 Zn: dithizone (530 nm) below 0.1 % (cl. 5); mercuric thiocyanate gravimetric above 0.1 %, factor 13.12 (cl. 6.3); mercuric thiocyanate volumetric (KIO<sub>3</sub>) up to 0.1 % (cl. 6.4).", "Part 5 Mn: bismuthate titrimetric, 0.1 to 1.5 % (scope; cl. 5 heading 0.01 to 1.5 %), factor 1.1. Periodate and persulphate methods deleted in this revision.", "Part 6 Mg: oxine method 0.01 to 12 %; gravimetric (factor 6.98) or volumetric bromate finish (cl. 5). EDTA method deleted in this revision.", "Part 7 Ni: dimethylglyoxime gravimetric up to 4 %, factor 20.32. Part 8 Cr: persulphate oxidation volumetric, factor 1.734 (no range stated).", "Part 9 Sn: iodimetric (KIO<sub>3</sub> 0.025 N) in CO<sub>2</sub> atmosphere, 2 to 5 g sample (no range stated). Part 10 Sb: potassium iodide–thiourea photometric, 0.40 g sample.", "Part 11 Ti: hydrogen peroxide photometric (about 410 nm); alternate diantipyrylmethane spectrophotometric 0.001 to 1.0 %. Part 12 V: N-cinnamoyl-N-phenylhydroxylamine spectrophotometric 0.005 to 0.02 % (new part).", "Foreword: Parts 13 to 16 (sodium, beryllium, zirconium, lithium) were under preparation. No precision data given in Parts 1 to 12.", "IS 1253 : 1992 cl. 6.2 names IS 504 as referee method for aluminium for iron and steel manufacture (DM/QA/WI/40 to 34).", "Lab SOP / WI (SOP/WI tab): DM/QA/WI/40, DM/QA/WI/41, DM/QA/WI/42, DM/QA/WI/43, DM/QA/WI/44, DM/QA/WI/45, DM/QA/WI/46"], "scope": "Chemical analysis of aluminium (impurities) — Si, Fe, Cu, Zn, Mn, Mg, Ni, Cr, Sn, Sb, Ti, V", "follow": "<table><tr><th>Part</th><th>Element</th><th>Method</th><th>Range, percent</th></tr><tr><td>1</td><td>Silicon</td><td>Spectrophotometric (815 nm)</td><td>Up to 0.10</td></tr><tr><td>1</td><td>Silicon</td><td>Molybdenum yellow photometric</td><td>0.02 to 0.3</td></tr><tr><td>1</td><td>Silicon</td><td>Gravimetric</td><td>Over 0.3</td></tr><tr><td>1</td><td>Lead</td><td>Sulphide colorimetric</td><td>—</td></tr><tr><td>2</td><td>Iron</td><td>O-phenanthroline spectrophotometric</td><td>0.03 to 0.10</td></tr><tr><td>2</td><td>Iron</td><td>Potassium dichromate titrimetric</td><td>Above 0.10</td></tr><tr><td>3</td><td>Copper</td><td>Diethyl-dithiocarbamate spectrophotometric</td><td>Up to 0.1</td></tr><tr><td>3</td><td>Copper</td><td>Iodimetric</td><td>Over 0.1</td></tr><tr><td>4</td><td>Zinc</td><td>Dithizone photometric</td><td>Below 0.1</td></tr><tr><td>4</td><td>Zinc</td><td>Mercuric thiocyanate gravimetric</td><td>Above 0.1</td></tr><tr><td>4</td><td>Zinc</td><td>Mercuric thiocyanate volumetric</td><td>Up to 0.1</td></tr><tr><td>5</td><td>Manganese</td><td>Bismuthate</td><td>0.1 to 1.5</td></tr><tr><td>6</td><td>Magnesium</td><td>Oxine (gravimetric / volumetric)</td><td>0.01 to 12</td></tr><tr><td>7</td><td>Nickel</td><td>Dimethylglyoxime gravimetric</td><td>Up to 4</td></tr><tr><td>8</td><td>Chromium</td><td>Persulphate oxidation volumetric</td><td>—</td></tr><tr><td>9</td><td>Tin</td><td>Iodimetric</td><td>—</td></tr><tr><td>10</td><td>Antimony</td><td>Potassium iodide–thiourea photometric</td><td>—</td></tr><tr><td>11</td><td>Titanium</td><td>Hydrogen peroxide photometric; alt. diantipyrylmethane</td><td>Alt.: 0.001 to 1.0</td></tr><tr><td>12</td><td>Vanadium</td><td>N-cinnamoyl-N-phenylhydroxylamine spectrophotometric</td><td>0.005 to 0.02</td></tr></table>", "keywords": "aluminium al purity impurities copper zinc magnesium silicon iron tin manganese shot notch bar wire ingot"}, {"id": "is1817", "no": "IS 1817 : 1961", "title": "Methods of Sampling Non-Ferrous Metals for Chemical Analysis", "cat": "Raw material", "facts": ["Adopted 14 November 1961; reaffirmed 2000, 2016 and 2021; second reprint June 1994 (cover of copy). Based on BS 1499 : 1949, ASTM E 55-48 and ASTM E 88-50T (cl. 0.3).", "Cl. 1: General principles of preparing samples of non-ferrous metals and alloys for chemical analysis; number of samples per lot and pieces per sample left to the material specification (for aluminium: IS 1253, 8.1).", "Cl. 3.1: Molten metal — three heavily chilled ingots from three spoonfuls (beginning, middle, end of tapping); convenient ingot size 150 × 50 × 6 mm. Cl. 3.2: granulated or splash (sheet less than 1 mm) sample for segregating / unmachinable metal.", "Cl. 4.1: Remelt solid metal where high accuracy is desired and remelting does not change composition. Cl. 4.2: milling or sawing across the whole cross section preferred; drillings as alternative.", "Cl. 4.2.1: Un-notched ingot — saw/mill at approx. ¼ of length from one end, or five drilled holes through total thickness. Cl. 4.2.2: lugs ≤ 25 mm thick — half a lug sawn and milled, or five holes. Cl. 4.2.3: notched ingot — break/saw at centre of notch, mill to 25 mm depth, or drill above the notches.", "Cl. 4.2.5 slabs and 4.2.6 billets/wire bars at ¼ length; 4.2.7 plates/sheets/strips (sheets at normally 45° or less to rolling direction); 4.2.8 wires — clippings from both ends of the coil; 4.2.9 scrap — remelt proportionate pieces without flux.", "Cl. 5.1: Remove foreign material and iron particles (strong magnet); mix, reduce; sample not less than 100 g; divide into three sealed parts — supplier, purchaser, referee. Cl. 5.2: storage in stoppered glass bottles or leakproof envelopes/cartons.", "Cl. 6: Clean surfaces; clean tools producing small uniform particles; avoid overheating/oxidation; no lubricant unless agreed; acid dip may be needed if low iron is critical.", "No tables in the standard; sampling planes shown in Fig. 1 to 3. No amendments listed in the copy.", "Lab SOP / WI (SOP/WI tab): DM/QA/SOP/04"], "scope": "Sampling of non-ferrous metals (aluminium) for chemical analysis", "follow": "<table><tr><th>Form</th><th>Clause</th><th>Preferred</th><th>Alternative</th></tr><tr><td>Molten metal</td><td>3.1</td><td>Three heavily chilled ingots (150 × 50 × 6 mm) from beginning, middle and end of tapping</td><td>Granulated / splash sample (3.2)</td></tr><tr><td>Un-notched ingot without lugs</td><td>4.2.1</td><td>Saw or mill whole section at approx. ¼ of length from one end</td><td>Five holes through total thickness in sampling plane</td></tr><tr><td>Un-notched ingot with lugs</td><td>4.2.2</td><td>Saw off half a lug (≤ 25 mm thick), mill sawn faces</td><td>Five holes through the lug</td></tr><tr><td>Notched ingot</td><td>4.2.3</td><td>Break/saw at centre of notch, mill faces to 25 mm depth</td><td>Holes through chilled section above the notches</td></tr><tr><td>Other shapes, castings, cakes</td><td>4.2.4</td><td>Mill or saw at suitable points</td><td>Five holes at suitable points</td></tr><tr><td>Wire</td><td>4.2.8</td><td>Clippings from both ends of the coil</td><td>—</td></tr></table><b>Preparation (5.1):</b> remove foreign material and iron (strong magnet), mix, reduce; mass not less than 100 g; divide into three sealed parts (supplier, purchaser, referee).", "keywords": "sampling aluminium al shot notch bar ingot wire deoxidant"}, {"id": "is438", "no": "IS 438 : 2006", "title": "Aluminium powder for explosives and pyrotechnic compositions — Specification (Second Revision)", "cat": "Raw material", "facts": ["1 Scope: requirements and methods of sampling and test for aluminium powder for use in explosive and pyrotechnic compositions.", "Second Revision; Reaffirmed 2021 (copy shows reaffirmations 2005 to 2016 and 2021). Amendment No. 1 (March 2015): Table 1, Sl No. ii) volatile matter for light grade — '0.25' substituted for '0.25 - 0.50'.", "3 Grades: (a) aluminium powder, light; (b) aluminium powder, heavy (also known as 'blown' aluminium powder); each of two sub-grades, I and II, depending on free metallic aluminium content and bulk density (3.1, 3.1.1).", "4.1 Description: light — flakes, free from visible impurities; heavy — compact, irregular and elongated particles (not flakes), free from visible impurities and foreign matter; aqueous extract not alkaline to phenolphthalein.", "4.2 Particle size as agreed between purchaser and supplier. 4.3 Gritty matter (Annex A): light sub-grade I max 0.01 percent (passes 125-micron IS Sieve), sub-grade II not traceable; heavy sub-grade I max 0.05 percent, sub-grade II max 0.1 percent (passes 425-micron IS Sieve).", "Table 1, Sl No. (ix) — free metallic aluminium, percent by mass, Min: Light I 87.0, Light II 85.0, Heavy I 98.0, Heavy II 90.0; method Annex K (4.4).", "Annex K (free metallic aluminium): about 0.1 g reacted with 20 ml 10 percent (m/v) NaOH in a 60 ml reaction bottle connected to a water-jacketed Lunge nitrometer (Fig. 1); stand 1 h; Al % = V(P − p) × 273 × 10^4 / [(273 + t) × 760 × 124 580 × M]; 100 g Al gives 124 580 ml H2 at NTP; zinc correction: 100 g Zn gives 34 253 ml H2 at NTP (ignore if metallic Zn < 0.1 percent).", "Annexes: A gritty matter; B matter soluble in ether; C volatile matter; D silicon; E copper; F iron; G zinc; H magnesium; J other metallic impurities (as Na); K free metallic aluminium; L apparent density; M water covering capacity; N sampling; P committee composition.", "6 Sampling as per Annex N. 7 Quality of reagents: pure chemicals and distilled water (IS 1070). Foreword: results rounded off as per IS 2 : 1960.", "Laboratory use: Annex K adapted (to be validated, ISO/IEC 17025 cl. 7.2.2.1) for aluminium shot / wire and remix / redex powder — DM/QA/WI/39.", "Lab SOP / WI (SOP/WI tab): DM/QA/WI/39"], "scope": "Free metallic aluminium — aluminium shot / wire (direct Al %) and remix / redex powder (adapted)", "follow": "<b>IS 438 : 2006, Table 1 Requirement for Aluminium Powder for Explosives and Pyrotechnic Compositions (Clause 4.4)</b><table><tr><th>Sl No.</th><th>Characteristic</th><th>Light Grade I</th><th>Light Grade II</th><th>Heavy Grade I</th><th>Heavy Grade II</th><th>Methods of Test, Ref to Annex</th></tr><tr><td>i)</td><td>Matter soluble in ether, percent by mass, Max</td><td>2.0 (1)</td><td>2.0 (1)</td><td>0.25 (1)</td><td>0.25 (1)</td><td>B</td></tr><tr><td>ii)</td><td>Volatile matter, percent by mass, Max</td><td>0.25 [Amd No. 1; was 0.25-0.50]</td><td>0.25 [Amd No. 1; was 0.25-0.50]</td><td>0.05</td><td>0.05</td><td>C</td></tr><tr><td>iii)</td><td>Silicon (as Si), percent by mass, Max</td><td>0.5</td><td>0.5</td><td>0.5</td><td>0.5</td><td>D</td></tr><tr><td>iv)</td><td>Copper (as Cu), percent by mass, Max</td><td>0.1</td><td>0.1</td><td>0.25</td><td>0.25</td><td>E</td></tr><tr><td>v)</td><td>Iron (as Fe), percent by mass, Max</td><td>1.0 (1)</td><td>1.0 (1)</td><td>1.0 (1)</td><td>1.0 (1)</td><td>F</td></tr><tr><td>vi)</td><td>Zinc (as Zn), percent by mass, Max</td><td>0.1</td><td>0.1</td><td>0.25</td><td>0.25</td><td>G</td></tr><tr><td>vii)</td><td>Magnesium (as Mg), percent by mass, Max</td><td>0.2</td><td>0.2</td><td>0.2</td><td>0.2</td><td>H</td></tr><tr><td>viii)</td><td>Other metallic impurities (as Na), percent by mass, Max</td><td>1.0</td><td>1.0</td><td>0.5</td><td>0.5</td><td>J</td></tr><tr><td>ix)</td><td><b>Free metallic aluminium, percent by mass, Min</b></td><td><b>87.0</b></td><td><b>85.0</b></td><td><b>98.0</b></td><td><b>90.0</b></td><td><b>K</b></td></tr><tr><td>x)</td><td>Apparent density, g/ml, Max</td><td>0.3</td><td>0.5</td><td>a) for material passing through 2.00 mm IS Sieve but retained on 425-micron IS Sieve: 0.9, Min<br>b) for material of other sizes: 1.0, Min</td><td>(same as Heavy Grade I)</td><td>L</td></tr><tr><td>xi)</td><td>Water covering, capacity cm2/g, Min (for use in commercial explosives)</td><td>9 000 (2)</td><td>—</td><td>—</td><td>—</td><td>M</td></tr></table>(1) For special requirements, the limits may be as agreed to between the purchaser and the supplier.<br>(2) Not applicable for fireworks.<br>Amendment No. 1 (March 2015): Table 1, Sl No. ii), col (3) and col (4) — substitute '0.25' for '0.25 - 0.50'.", "keywords": "metallic aluminium al% purity hydrogen evolution gas volumetric nitrometer shot wire remix redex"}, {"id": "jisg2404", "no": "JIS G 2404 : 2022", "title": "Methods for chemical analysis of aluminium dross for iron and steel making", "cat": "Raw material", "facts": ["Only the preview of this standard is available; methods not included.", "Established 2015-09-24; revised 2022-12-20 (replaces JIS G 2404 : 2015, technically revised). English edition by JSA, 2023-04.", "1 Scope: methods for determination of metallic aluminium, nitrogen, chlorine, fluorine, total silicon, aluminium oxide and carbon, and the moisture content in aluminium dross used as a flux in the manufacture of iron and steel.", "5 Metallic aluminium: 5.2 ICP-AES for decomposed and separated metallic Al; 5.3 zinc back-titration for decomposed and separated metallic Al; 5.4 gas volumetric method by dissolution with hydrochloric acid; 5.5 measurement using reaction solution temperature.", "6 Nitrogen: 6.2 back titration by sodium hydroxide/sulfuric acid for distilled and separated ammonia.", "7 Chlorine: 7.2 ion chromatography; 7.3 silver nitrate titration.", "8 Fluorine: 8.2 lanthanum and alizarin complexon absorptiometry following alkali fusion and distilled separation; 8.3 ion chromatography following thermal hydrolysis.", "9 Total silicon: 9.2 molybdo silicic acid absorptiometry; 9.3 silicon dioxide gravimetric method.", "10 Aluminium oxide: 10.2 ICP-AES; 10.3 zinc back-titration.", "11 Carbon: 11.2 infrared absorption after combustion. 12 Moisture: 12.2 drying loss method. 13 Report.", "2 Normative references include JIS G 2402 (Aluminium dross for iron and steel making), JIS G 2403 (sampling and sample preparation), JIS H 4160, JIS H 6201, JIS K 0050, K 0101, K 0102, K 0115, K 0116, K 0127, K 0211, K 0215, K 0970, K 8005, JIS R 1306.", "Warning (clause 1): caution with high pressure gas (ICP-AES, combustion IR) and dangerous chemicals (e.g. bromine, hydrofluoric acid, organic solvent).", "Lab SOP / WI (SOP/WI tab): DM/QA/WI/50"], "scope": "Aluminium dross (remix / redex) for steel making — metallic Al, Al2O3, N, Cl, F, Si, C, moisture", "follow": null, "keywords": "remix redex aluminium dross al2o3 alumina total aluminium deoxidiser powder"}, {"id": "is1559", "no": "IS 1559 : 1961", "title": "Methods of Chemical Analysis of Ferro-Alloys", "cat": "Raw material", "facts": ["Reaffirmed 2002, 2012, 2018 and 2023 (cover page of copy).", "Cl. 1.1: nine sections — ferrosilicon, ferrochromium, ferromanganese and speigeleisen, silicomanganese, ferromolybdenum, ferrophosphorus, ferrotitanium, ferrovanadium, ferrotungsten; composition ranges in Appendix A.", "Cl. 2.1: sampling per IS 1472 (Part I)-1959 (latest version applies per cl. 0.5 — now IS 1472 : 1977). Cl. 3.1: pure chemicals and distilled water (IS 1070-1960). Cl. 4.1: Whatman filter paper numbers. Cl. 0.6: rounding per IS 2-1960.", "Section IV Silicomanganese: cl. 24 Si gravimetric (0.5 g, 50-ml iron crucible, ~10 g + 2 g Na<sub>2</sub>O<sub>2</sub>; then 5.4.2 to 5.5); cl. 25 Mn bismuthate (filtrate of 24 to 500 ml, 25 ml aliquot; 19.3.2 to 19.4); cl. 26 Mn Volhard alternate (cl. 20); cl. 27 C total combustion gravimetric (cl. 7 with 1 g sample, 1 200 to 1 300 °C); cl. 28 C combustion volumetric alternate (cl. 8); cl. 29 P alkalimetric (printed 'under 22'; completes per 23.3.1, 23.3.2; dissolution in platinum dish with 50 ml HNO<sub>3</sub> + 10 to 15 ml HF); cl. 30 S gravimetric (cl. 9, 5 g).", "Appendix A silicomanganese: Si 16 to 20, C 2.0 Max, P 0.30 Max, Mn 65 to 75, S 0.03 Max, Al Nil (percent).", "No precision (repeatability/reproducibility) data given.", "IS 1470 : 2025 cl. 7.2.5: IS 1559 is the referee method for silicomanganese in case of dispute.", "Lab SOP / WI (SOP/WI tab): DM/QA/WI/29, DM/QA/WI/30, DM/QA/WI/31, DM/QA/WI/32, DM/QA/WI/33, DM/QA/WI/34, DM/QA/WI/35"], "scope": "Silico manganese — Si, Mn, C, P, S analysis", "follow": "<b>Appendix A — Composition ranges (Silicomanganese row), percent</b><table><tr><th>Si</th><th>C</th><th>P</th><th>Mn</th><th>S</th><th>Al</th></tr><tr><td>16 to 20</td><td>2.0 Max</td><td>0.30 Max</td><td>65 to 75</td><td>0.03 Max</td><td>Nil</td></tr></table><b>Section IV clauses</b><ul><li>24 Silicon — gravimetric (DM/QA/SOP/15)</li><li>25 Manganese — bismuthate; 26 Volhard alternate (DM/QA/SOP/16)</li><li>27 Carbon (total) — direct combustion gravimetric; 28 volumetric alternate (DM/QA/SOP/17)</li><li>29 Phosphorus — alkalimetric (DM/QA/SOP/18)</li><li>30 Sulphur — gravimetric (DM/QA/SOP/19)</li></ul>", "keywords": "silicon si% silico manganese simn manganese mn% bismuthate silico manganese simn carbon c% combustion silico manganese simn phosphorus p% silico manganese simn sulphur sulfur s% silico manganese simn"}, {"id": "is1472", "no": "IS 1472 : 1977", "title": "Methods for Sampling Ferro-Alloys for Determination of Chemical Composition (First Revision)", "cat": "Raw material", "facts": ["Reaffirmed 1996, 2011, 2017 and 2022; Amendment No. 1 (July 1988) and Amendment No. 2 (September 2000) included in copy.", "Cl. 1.2: silicomanganese is a Group III alloy (with ferromanganese, ferrochromium high carbon, ferrophosphorous).", "Group III lump: lots not more than 5 000 t, sub-lots per Table 1 (5.2.3.1); gross sample not less than 100 kg per sub-lot by sample cutter or square-frame method from one in five wagons/trucks, at least two increments each (5.2.3.2, 5.2.3.3 Amd 1); stockpile trench sampling, at least 25 percent of stockpiles (5.2.3.4).", "Group III crushed in containers: one out of every five containers opened, gross sample 100 kg (5.3.3.2 Amd 1).", "Preparation (6.1.3 Amd 1): crush to pass 5-mm sieve, reduce to not less than 20 kg, cone and quarter to not less than 500 g, pulverise to pass 150-micron sieve totally; divide into three — buyer, seller, referee (6.1.10).", "Table 6: silicomanganese — Si, Mn, C analysed individually; S, P, As on composite sample (7.1).", "Reporting 8.1: two samples — average and individual results; three or more — x&#772; ± hR (h = 1.30, 0.72, 0.51, 0.29, 0.23 for 3, 4, 5, 8, 10 samples).", "Lab SOP / WI (SOP/WI tab): DM/QA/SOP/02"], "scope": "Sampling of ferro-alloys (SiMn)", "follow": "<b>Table 1 Minimum number of sub-lots</b><table><tr><th>Mass of the Lot (tonnes)</th><th>Minimum Number of Sub-lots</th></tr><tr><td>Up to 25</td><td>1</td></tr><tr><td>26 to 100</td><td>2</td></tr><tr><td>101 to 300</td><td>3</td></tr><tr><td>301 to 800</td><td>4</td></tr><tr><td>801 to 1 500</td><td>5</td></tr><tr><td>1 501 to 3 000</td><td>8</td></tr><tr><td>3 001 and above</td><td>10</td></tr></table><b>Table 6 (Group III — Silicomanganese)</b><table><tr><th>Individually</th><th>Composite</th></tr><tr><td>Silicon, Manganese, Carbon</td><td>Sulphur, Phosphorus, Arsenic</td></tr></table><ul><li>Gross sample: not less than 100 kg per sub-lot (5.2.3.2, 5.2.3.3, 5.3.3.2 — Amd 1)</li><li>Lab sample: 5 mm → ≥20 kg → coning &amp; quartering ≥500 g → 150-micron totally (6.1.3 — Amd 1)</li></ul>", "keywords": "sampling sample silico manganese simn ferro alloy"}, {"id": "fesdust", "no": "FES dust — Zinc", "title": "Zinc test in fume extraction system (FES) dust", "cat": "By-product", "facts": ["Checked and NOT applicable: IS 4611 : 1991 (metallic zinc powder / zinc dust — a zinc product, not steel plant dust) and IS 3815 series (zinc and zinc alloys)", "International methods exist for zinc in zinc sulfide concentrates (e.g. ISO 13658 — hydroxide precipitation & EDTA titration), but they are not written for steel plant dust", "Lab WIs: DM/QA/WI/47 (ferrocyanide) and DM/QA/WI/48 (EDTA, ion exchange) adapted from IS 9252 : 1979; DM/QA/WI/49 = routine lab method (HCl + HNO3, ammonia separation with ammonium sulphate and potassium fluoride, EDTA titration with xylenol orange); validation required"], "scope": "FES / bag-filter dust from the SMS", "keywords": "fes dust zinc zn fume extraction bag filter furnace dust", "follow": "Method used: IS 9252 : 1979 (volumetric zinc) adapted for FES dust - see DM/QA/WI/47 and DM/QA/WI/48; routine lab method DM/QA/WI/49 (ammonia separation, EDTA, xylenol orange)."}, {"id": "is9252", "no": "IS 9252 : 1979", "title": "Method for Determination of Zinc (Volumetric)", "cat": "Chemical", "facts": ["Reaffirmed 1998, 2015, 2020 and 2024 (cover page of copy).", "Cl. 1.1: prescribes volumetric determination of zinc using (a) potassium ferrocyanide and (b) EDTA. Cl. 0.3: intended to achieve uniformity of zinc determination prescribed in various Indian Standards; cl. 0.4: based on JIS M 8124-1965 (zinc in ores).", "Cl. 2.1: pure chemicals and distilled water (IS 1070-1977). Cl. 0.5: rounding per IS 2-1960.", "Cl. 3 Potassium ferrocyanide method: 0.3 to 1 g sample, HCl + HNO<sub>3</sub> decomposition, H<sub>2</sub>S separation of Cd/Cu at 80 to 90 °C, double NH<sub>4</sub>OH/bromine (or persulphate) separation of Fe/Mn, titration at 75 to 80 °C with K<sub>4</sub>Fe(CN)<sub>6</sub> (21.6 g/L) using uranyl external indicator, yellowish green to pale brown.", "Cl. 4 EDTA method: 0.3 to 1 g sample, strongly basic anion exchange resin column (Fig. 1, ~20 g resin, 215 to 150 micron), elution with 180 ml ammoniacal eluent, titration at pH 5.0 to 5.5 with EDTA using xylenol orange, pink to yellow.", "Cl. 4.3.15 EDTA standard solution printed as '0.5 M' with 18.610 g/L (1 ml ≈ 3.269 mg Zn); cl. 4.3.14 refers to 'EDTA standard solution (0.05 M)'. Cl. 4.3.15.2: 0.01 M EDTA for samples with small zinc content.", "Result: Zn (as Zn) % by mass = m × (V<sub>1</sub> − V<sub>2</sub>) / M × 100 (cl. 3.4, 4.5.1).", "No range of applicability, precision data or referee method given. Use for FES dust is a laboratory adaptation requiring validation (ISO/IEC 17025:2017, cl. 7.2.2.1) — see DM/QA/WI/47 and DM/QA/WI/48.", "Lab SOP / WI (SOP/WI tab): DM/QA/WI/47, DM/QA/WI/48"], "scope": "Zinc in FES / bag-filter dust (adapted method)", "follow": "<b>Methods in IS 9252 : 1979</b><table><tr><th>Item</th><th>A: Potassium ferrocyanide (cl. 3)</th><th>B: EDTA (cl. 4)</th></tr><tr><td>Sample mass</td><td>0.3 to 1 g</td><td>0.3 to 1 g</td></tr><tr><td>Titrant</td><td>Potassium ferrocyanide, 21.6 g/L</td><td>EDTA '0.5 M', 18.610 g/L (as printed); 0.01 M for low Zn</td></tr><tr><td>Standardised against</td><td>0.25 g zinc</td><td>0.15 g zinc</td></tr><tr><td>Indicator / end point</td><td>Uranyl salt (external), yellowish green to pale brown, 75 to 80 °C</td><td>Xylenol orange, pink to yellow, pH 5.0 to 5.5</td></tr></table>", "keywords": "zinc zn fes dust bag filter fume extraction ferrocyanide edta"}, {"id": "is381", "no": "IS 381 : 2024", "title": "Sodium Silicate — Specification (Third Revision)", "cat": "Raw material", "facts": ["Third Revision, March 2024 (first published 1952, revised 1972 and 1995); Inorganic Chemicals Sectional Committee, CHD 01. No amendments listed in the copy.", "Cl. 1: requirements and method of sampling for sodium silicate, in solid and liquid forms, for use in various industries.", "Cl. 3: grades — neutral and alkaline (solid and liquid). Cl. 4.1: liquid neutral Type 1 (pharmaceutical and toilet preparations), Type 2 (adhesive and other purposes). Cl. 4.2: liquid alkaline Types 1, 2 and 3 (soap, detergent, textile, welding electrode and cement industries).", "Cl. 5.1: clear, free from dirt and visible impurities; liquid — thick, viscid, translucent, white or slightly grey; solid — glassy lumps of pale grey or green colour.", "Cl. 5.2 / Table 1: requirements tested by IS 14212 methods; clause references in col (10).", "Annex A: alternate instrumental methods — A-1 iron by ICP-OES (Fe 238.204, 259.940, 271.441 nm; about 2.5 g sample in 50 ml with 1.0 ml HNO3; result in mg/kg × 20 dilution factor); A-2 chlorides and sulphates by ion chromatography (1 g to 5 g sample in 25 ml reagent water).", "Annex B: lot = one grade, single batch; drums per Table 3 (3/5/7/10/15); about 500 g (solid) or 300 g (liquid) per drum; composite about 300 g divided in three (purchaser, supplier, referee).", "B-4.1: total soluble silicates and Na2O : SiO2 ratio on any three individual samples; B-4.2: all other tests on composite sample; B-5: lot conforms if B-5.1 and B-5.2 satisfied.", "Foreword: results rounded off as per IS 2 : 2022.", "Lab SOP / WI (SOP/WI tab): DM/QA/SOP/05, DM/QA/WI/51, DM/QA/WI/52, DM/QA/WI/53, DM/QA/WI/54, DM/QA/WI/55, DM/QA/WI/56, DM/QA/WI/57, DM/QA/WI/58, DM/QA/WI/59, DM/QA/WI/60, DM/QA/WI/61, DM/QA/WI/62, DM/QA/WI/63, DM/QA/WI/64"], "scope": "Sodium silicate — all Table 1 tests", "follow": "<b>IS 381 : 2024 Table 1 Requirements for Sodium Silicate</b><table><tr><th>Sl No.</th><th>Characteristic</th><th>Liquid Neutral Type 1 (3)</th><th>Liquid Neutral Type 2 (4)</th><th>Liquid Alkaline Type 1 (5)</th><th>Liquid Alkaline Type 2 (6)</th><th>Liquid Alkaline Type 3 (7)</th><th>Solid Neutral (8)</th><th>Solid Alkaline (9)</th><th>Method of Test [Ref to Clause in IS 14212] (10)</th></tr><tr><td>i)</td><td>Matter insoluble in water, percent by mass, Max</td><td>0.1</td><td>0.2</td><td>0.2</td><td>0.2</td><td>0.2</td><td>4.0</td><td>1.5</td><td>A-3</td></tr><tr><td>ii)</td><td>Relative density at 27/27 °C</td><td>1.39 to 1.41</td><td>1.39 to 1.41</td><td>1.69 to 1.71</td><td>1.54 to 1.56</td><td>1.34 to 1.36</td><td>–</td><td>–</td><td>A-5</td></tr><tr><td>iii)</td><td>Total soluble silicates, percent by mass, Min</td><td>38</td><td>38</td><td>54</td><td>48</td><td>30</td><td>95</td><td>98</td><td>A-7 or A-12</td></tr><tr><td>iv)</td><td>Ratio of total alkalinity (as Na2O) to total soluble silica (as SiO2) (Na2O : SiO2)</td><td>1 : 3.2 ± 0.1</td><td>1 : 3.2 ± 0.1</td><td>1 : 2.0 ± 0.1</td><td>1 : 2.0 ± 0.1</td><td>1 : 2.0 ± 0.1</td><td>1 : 3.2 ± 0.1</td><td>1 : 2.0 ± 0.1</td><td>A-9</td></tr><tr><td>v)</td><td>Loss in mass on ignition, percent by mass, Max</td><td>–</td><td>–</td><td>–</td><td>–</td><td>–</td><td>1.0</td><td>0.5</td><td>A-10</td></tr><tr><td>vi)</td><td>Iron as (Fe), percent by mass, Max</td><td>0.005</td><td>0.02</td><td>0.02</td><td>0.02</td><td>0.02</td><td>0.04</td><td>0.04</td><td>A-11</td></tr><tr><td>vii)</td><td>Viscosity at 20 °C</td><td>200 to 500</td><td>–</td><td>–</td><td>–</td><td>–</td><td>–</td><td>–</td><td>A-12</td></tr><tr><td>viii)</td><td>Chloride (as NaCl), percent by mass, Max</td><td>0.25</td><td>–</td><td>–</td><td>–</td><td>–</td><td>–</td><td>–</td><td>A-14</td></tr><tr><td>ix)</td><td>Sulphate (as Na2SO4), percent by mass, Max</td><td>0.2</td><td>–</td><td>–</td><td>–</td><td>–</td><td>–</td><td>–</td><td>A-15</td></tr></table><br><b>Table 3 Number of Drums to be Selected (B-2.2)</b><table><tr><th>Lot size N</th><th>Drums n</th></tr><tr><td>Up to 10</td><td>3</td></tr><tr><td>11 to 20</td><td>5</td></tr><tr><td>21 to 30</td><td>7</td></tr><tr><td>31 to 50</td><td>10</td></tr><tr><td>51 and above</td><td>15</td></tr></table>", "keywords": "sodium silicate na2o sio2 ratio density insoluble viscosity chloride sulphate iron"}, {"id": "is14212", "no": "IS 14212 : 1995", "title": "Sodium and Potassium Silicates — Methods of Test", "cat": "Raw material", "facts": ["Reaffirmed 2021 (latest reaffirmation seen on copy); CHD 003. No amendments listed in the copy.", "Cl. 1.1: methods of test for sodium and potassium silicates; cl. 3.1: methods given in Annex A.", "A-1: pure chemicals and reagent grade water (IS 1070 : 1992).", "A-2: prepared sample solution — about 20 g in 500 ml; solids digested in autoclave 2 h at 4 kg/cm2 (alkaline: 10 times water; neutral: crushed to 150 micron, twice water).", "A-3: matter insoluble in water — about 25 g, Gooch crucible, 110 ± 5 °C.", "A-4: specific gravity — Twaddell hydrometer at 15.5 °C.", "A-5: relative density 27/27 °C — wide neck pyknometer, water bath 27 ± 0.5 °C.", "A-6: total soluble silica (as SiO2), gravimetric — double HCl dehydration, ignition 950 to 975 °C, HF volatilization.", "A-7: total alkalinity (as M2O) — 1 N HCl, methyl orange; Na2O % = 3.10 V/m; K2O % = 4.71 V/m.", "A-8: total soluble silicates = SiO2 (A-6) + alkalinity (A-7).", "A-9: ratio of total alkalinity to total soluble silica; mass ratio gives molar ratio for sodium silicate; multiply by 1.567 for potassium silicate.", "A-10: loss in mass on ignition — about 5 g, platinum crucible.", "A-11: iron (as Fe) — butanolic thiocyanate, Nessler cylinders; Fe % = 0.001 V/M.", "A-12: viscosity — torsion viscometer at 20 °C, result in centipoises.", "A-13: alternate titrimetric method for silica — sodium fluoride, factor 7.510.", "A-14: chloride (as NaCl) — Volhard, 10 g sample; % = (V1 − V2) × 0.058.", "A-15: sulphate (as SO4) — BaSO4 gravimetric with HF treatment; % = 41.157 m1/m0.", "Lab SOP / WI (SOP/WI tab): DM/QA/WI/51, DM/QA/WI/52, DM/QA/WI/53, DM/QA/WI/54, DM/QA/WI/55, DM/QA/WI/56, DM/QA/WI/57, DM/QA/WI/58, DM/QA/WI/60, DM/QA/WI/61, DM/QA/WI/63"], "scope": "Methods of test for sodium silicate", "follow": null, "keywords": "sodium silicate na2o sio2 ratio density insoluble viscosity chloride sulphate iron"}, {"id": "is14650", "no": "IS 14650 : 2023", "title": "Unalloyed and alloyed steel ingot and semi-finished products for re-rolling purposes — Specification", "cat": "Product (Billet)", "facts": ["Supersedes IS 14650:1999, IS 2830:2012, IS 2831:2012, IS 8052:2006, IS 8951:2001 and IS 8952:2005 (BIS circular, effective 28 Sep 2024)", "Scope (Cl. 1.1): ingots and semi-finished products (billets, blooms, slabs) for rolling into products of the applicable Indian Standard; not for forging ingots or welding electrodes", "Designation (Cl. 5): IS 14650 CPS <product standard>/<grade>, e.g. IS 14650 CPS 1786/Fe 500D, IS 14650 CPS 2062/E250 BR", "Chemistry (Cl. 7.1): must meet the LADLE analysis of the product standard it will be rolled into; IS 228 or approved instrumental method, IS 228 is the referee method", "No element to be added intentionally without purchaser agreement (Cl. 7.1.2)", "Check (product) analysis from the standard position; permissible variation as per product standard; not applicable to rimming steel (Cl. 7.2)", "At least one ladle analysis from each cast (Cl. 8); billet sample location as per Fig. 1 (Cl. 9.2)"], "scope": "MS Billets — chemistry (C, Mn, Si, S, P etc.) is checked against the grade of the product the billet is meant for", "follow": "<ul><li><b>Billet size tolerance (Cl. 11.2):</b> up to 75 mm ±1.5; 75–125 mm ±3.0; 125–150 mm +4.0/−3.0; over 150 mm +6.0/−3.0 mm</li><li><b>Length (Cl. 11.4):</b> ±150 mm on specified length</li><li><b>Out-of-square (Cl. 11.7):</b> up to 150 mm — 5 mm max; over 150 mm — 7 mm max</li><li><b>Freedom from defects (Cl. 12.2):</b> no cracks, surface flaws, laminations, rough/jagged/imperfect edges</li><li><b>Optional tests (Cl. 13.1):</b> Macro (IS 11371), Sulphur print (IS 12037), Inclusion content (IS 4163) — limits by agreement unless product standard gives them</li><li><b>Marking (Cl. 14.2):</b> each piece stamped / painted / heat-proof label with the <b>cast number</b></li></ul>"}, {"id": "is10748", "no": "IS 10748 : 2025", "title": "Hot-rolled steel strip for welded tubes and pipes — Specification (Third Revision)", "cat": "Product (Strip)", "facts": ["Supersedes IS 10748:2004 (BIS committee MTD 04)", "Values below are from the BIS wide-circulation draft of this revision (Feb 2025); confirm against your published 2025 copy", "Ladle analysis by IS 228 or any established instrumental/chemical method (Cl. 7.1)", "Tensile test per IS 1608 (Part 1), gauge length 5.65√So; transverse test piece (longitudinal allowed below 600 mm width) (Cl. 8.2)", "2 tensile + 2 bend samples per cast/heat of same grade and condition (Cl. 8.1, 9.1); bend cold through 180° (Cl. 9.2.4)", "Thickness & width tolerance as per IS 1852 (Cl. 13.1); edge camber: cut length 0.5% × length, coil 25 mm in any 5000 mm (Cl. 13.2)", "Coil marking: manufacturer name/trade-mark, grade, cast no., size, coil mass (Cl. 16.1)"], "scope": "HR strip from the Strip Mill (for pipes / tubes)", "follow": "<b>Chemistry, max % (Table 1, ladle):</b><table style='width:100%;font-size:12px;border-collapse:collapse;margin:4px 0'><tr><th>Gr</th><th>C</th><th>Mn</th><th>S</th><th>P</th><th>CEV</th></tr><tr><td>1</td><td>0.10</td><td>0.50</td><td>0.04</td><td>0.04</td><td>–</td></tr><tr><td>2</td><td>0.12</td><td>0.80</td><td>0.04</td><td>0.04</td><td>–</td></tr><tr><td>3</td><td>0.20</td><td>1.20</td><td>0.04</td><td>0.04</td><td>–</td></tr><tr><td>4</td><td>0.20</td><td>1.30</td><td>0.04</td><td>0.04</td><td>0.45</td></tr><tr><td>5</td><td>0.25</td><td>1.40</td><td>0.04</td><td>0.04</td><td>0.45</td></tr><tr><td>6</td><td>0.25</td><td>1.50</td><td>0.04</td><td>0.04</td><td>0.45</td></tr><tr><td>7</td><td>0.25</td><td>1.60</td><td>0.04</td><td>0.04</td><td>0.50</td></tr><tr><td>8</td><td>0.25</td><td>1.65</td><td>0.04</td><td>0.04</td><td>0.52</td></tr></table><b>Mechanical, min (Table 5):</b><table style='width:100%;font-size:12px;border-collapse:collapse;margin:4px 0'><tr><th>Gr</th><th>UTS MPa</th><th>YS MPa</th><th>El %</th><th>Bend ID</th></tr><tr><td>1</td><td>290</td><td>170</td><td>30</td><td>t</td></tr><tr><td>2</td><td>330</td><td>210</td><td>28</td><td>2t</td></tr><tr><td>3</td><td>410</td><td>240</td><td>23</td><td>2t</td></tr><tr><td>4</td><td>430</td><td>275</td><td>22</td><td>3t</td></tr><tr><td>5</td><td>450</td><td>310</td><td>21</td><td>3t</td></tr><tr><td>6</td><td>490</td><td>355</td><td>20</td><td>3t</td></tr><tr><td>7</td><td>540</td><td>410</td><td>18</td><td>3t</td></tr><tr><td>8</td><td>570</td><td>450</td><td>17</td><td>3t</td></tr></table>Fine-grain grades E275H, E355H, E420H, E460H (Tables 2 &amp; 6): S ≤ 0.025, P ≤ 0.03, Al(total) ≥ 0.02; CEV 0.40 / 0.43 / 0.48 / 0.53; YS 275 / 355 / 420 / 460 MPa."}, {"id": "is8811", "no": "IS 8811 : 1998", "title": "Method for Emission Spectrometric Analysis of Plain Carbon and Low Alloy Steels Point to Plane Technique (First Revision)", "cat": "Chemical", "facts": ["Cl. 1.1: Generalised spark emission spectrometric procedure for plain carbon and low alloy steels with minimum iron content of 94 percent; lines and ranges given for information.", "Cl. 1.1: Internal standard line Fe 271.44 nm for all elements.", "Cl. 4.5: Laboratory 19 °C to 25 °C, RH 45 to 60 percent, dust-free; Cl. 4.6 power tolerance ± 5 percent (preferably ± 2 percent).", "Cl. 5.1: Counter electrode pure silver or thoriated tungsten; Cl. 6.4: argon purity 99.995 percent minimum.", "Cl. 9.1: Sample approx. 30 to 40 mm diameter, 10 to 20 mm thick; Cl. 9.6: final finish with 60/120 grit paper.", "Cl. 12.3: Excite sample in duplicate or triplicate; Cl. 12.4: concentration from average intensity via working curve.", "No precision (repeatability/reproducibility) data given in the standard.", "First published 1978; first revision February 1998; Reaffirmed 2012, 2018 (as seen on copy cover). No amendments listed in the copy.", "Lab SOP / WI (SOP/WI tab): DM/QA/WI/05"], "scope": "C, Cr, Cu, Mn, P, Si, S in Low Alloy Steel (TMT Bars) and Plain Carbon / Low Alloy Steel (MS Billets)", "follow": "<table><tr><th>Element</th><th>Analytical line (nm)</th><th>Internal std line (nm)</th><th>Range (percent by mass)</th></tr><tr><td>Carbon</td><td>193.09</td><td>271.44</td><td>0.01 to 1.5</td></tr><tr><td>Chromium</td><td>298.92, 267.72</td><td>271.44</td><td>0.05 to 5.0</td></tr><tr><td>Copper</td><td>327.40, 213.6</td><td>271.44</td><td>0.01 to 0.5</td></tr><tr><td>Manganese</td><td>293.31, 255.86</td><td>271.44</td><td>0.01 to 2.0</td></tr><tr><td>Phosphorus</td><td>178.29</td><td>271.44</td><td>0.005 to 0.10</td></tr><tr><td>Silicon</td><td>288.16, 51.61 (as printed)</td><td>271.44</td><td>0.05 to 2.0</td></tr><tr><td>Sulphur</td><td>180.73</td><td>271.44</td><td>0.005 to 0.10</td></tr></table><br><b>Sample (9.1):</b> approx. 30 to 40 mm dia, 10 to 20 mm thick; homogeneous, free from porosity, voids and inclusions.<br><b>Lab (4.5):</b> 19 °C to 25 °C, RH 45 to 60 percent, dust-free. <b>Argon (6.4):</b> 99.995 percent min.", "keywords": "oes spectrometer spectro emission c mn si s p cr cu steel billet tmt"}, {"id": "is15774", "no": "IS 15774 : 2018", "title": "Sponge Iron/Direct Reduced Iron (DRI) Hot Briquetted Iron (HBI) and Cold Briquetted Iron (CBI) for Steel Making (First Revision)", "cat": "Raw material", "facts": ["Cl. 1: Covers sponge iron/DRI, HBI and cold briquettes for steel making in electric arc furnace (EAF) and induction furnaces; also used in blast furnaces and LD converter.", "First Revision, October 2018; Reaffirmed 2023; no amendments listed in the copy.", "Cl. 3.1: Sponge iron/DRI = product with metallization degree greater than 82 percent; Cl. 3.4: Fe(T) = Fe(M) + Fe(O).", "Cl. 3.10: Degree of metallization = Mass of metallic iron × 100 / Mass of total iron; Cl. 3.10.1: Equivalent metallization = Degree of metallization + 5 times percent total carbon.", "Cl. 5.1-5.3: Chemical composition per Table 1 (lumps & HBI, Grades A/B/C), Table 2 (fines 0 to 4 mm), Table 3 (cold briquettes).", "Cl. 5.4: Other constituents incl. total iron by IS 1493 / IS 1493 (Part 1) or other established instrumental/chemical method; in dispute, latest IS 1493 is the Referee Method.", "Cl. 5.5: Metallic iron by ferric chloride method (Annex A, 1 g sample) with +0.8 percent metallization correction factor allowed; referee = bromine methanol method (Annex B, 0.5 g sample), no correction factor. Carbon by IS 228 (Part 1).", "Cl. 8.1.3: Only the magnetic portion considered for chemical analysis; Annex C: test sample 100 g min at minus 150 microns (C-6.2.1); reserve samples retained 6 months (C-7).", "Annex C sampling: Table 4 min increment mass by top size (12/10/8 kg), Table 5 number of increments by lot mass (35 down to 6); bagged DRI: 25 bags per 100 mt, 25 increments of 2 kg = 50 kg gross sample.", "Annex D (HBI): 1 gross sample per 500 t or less, 10 increments of 10 kg; Annex E (cold briquettes): 10 increments of 2.5 kg = 25 kg.", "Lab SOP / WI (SOP/WI tab): DM/QA/SOP/01, DM/QA/WI/10, DM/QA/WI/11, DM/QA/WI/12 (sampling and reagents only; HgCl2 Fe(M) is a lab method), DM/QA/WI/16, DM/QA/WI/20, DM/QA/WI/22"], "scope": "Sponge iron — Fe(M), chemistry, size, sampling", "follow": "<b>Table 1 Chemical Composition of Sponge Iron/DRI (Lumps) and HBI (Clause 5.1)</b>\n<table><tr><th>Sl No.</th><th>Constituents</th><th>Grade (A)</th><th>Grade (B)</th><th>Grade (C)</th></tr>\n<tr><td>i)</td><td>Total iron, percent</td><td>89-93</td><td>88, Min</td><td>85 to &lt;88</td></tr>\n<tr><td>ii)</td><td>Metallic iron, percent</td><td>80, Min</td><td>76, Min</td><td>70, Min</td></tr>\n<tr><td>iii)</td><td>Metallization, percent</td><td>88, Min</td><td>86, Min</td><td>82, Min</td></tr>\n<tr><td>iv)</td><td>Carbon content: a) Gas based sponge iron/DRI</td><td>≥ 1.0</td><td>≥ 1.0</td><td>≥ 1.0</td></tr>\n<tr><td></td><td>b) HBI</td><td>1.1 and above</td><td>0.97 - &lt;1.1</td><td>0.97 - &lt;1.1</td></tr>\n<tr><td></td><td>c) Coal based sponge iron/DRI</td><td>0.08-0.12</td><td>0.08-0.12</td><td>0.08-0.12</td></tr>\n<tr><td>v)</td><td>Sulphur, Max: a) Gas based sponge iron/DRI</td><td>0.005</td><td>0.005</td><td>0.005</td></tr>\n<tr><td></td><td>b) HBI</td><td>0.005</td><td>0.005</td><td>0.005</td></tr>\n<tr><td></td><td>c) Coal based sponge iron/DRI</td><td>0.030</td><td>0.030</td><td>0.030</td></tr>\n<tr><td>vi)</td><td>Phosphorus, Max</td><td>0.060</td><td>0.070</td><td>0.100</td></tr>\n<tr><td>vii)</td><td>SiO2 + Al2O3, Max</td><td>6</td><td>7</td><td>8</td></tr>\n<tr><td>viii)</td><td>Combined total Pb, Zn, Cu, Sn, Cr, Ni, and As, Max</td><td>0.010</td><td>0.015</td><td>0.015</td></tr></table>\nNOTES (Table 1):<ul>\n<li>1 The above chemical composition does not include Briquetted HBI fines.</li>\n<li>2 Higher carbon content may also be supplied.</li>\n<li>3 Metallic iron = Total iron × Degree of metallization / 100</li>\n<li>4 Although FeO content of sponge iron/DRI is an important constituent, it is generally not specified because its content will depend on the original Fe content of the ore. Higher the Fe content of the ore used for direct reduction, higher will be FeO in the sponge iron/DRI and HBI for the same degree of metallization.</li>\n<li>5 For any given degree of metallization, the equivalent metallization would vary depending upon the total carbon content of the sponge iron/DRI and HBI, which has to be agreed mutually between the supplier and the purchaser. Therefore, the equivalent degree of metallization has not been indicated in Table 1.</li>\n<li>6 For use of sponge iron/direct reduced iron (DRI), hot briquetted iron (HBI)/cold briquetted iron (CBI) in induction furnaces, the recommended phosphorus content should be less than 0.08 percent. The manufacturer of steel through induction furnaces may use appropriate quantity of steel scrap so as to meet the phosphorus content and other chemical constituents of end product specification.</li></ul><br><b>Table 2 Chemical Composition of Sponge Iron/DRI Fines (Clause 5.2)</b>\n<table><tr><th>Size, mm</th><th>Total Iron, Percent, Min</th><th>FeM, Percent, Min</th><th>C, Percent</th><th>S, Percent, Max</th><th>P, Percent, Max</th></tr>\n<tr><td>0 to 4</td><td>89</td><td>80</td><td>0.08 - 0.15</td><td>0.03</td><td>0.06</td></tr></table>\nNOTES (Table 2):<ul><li>1 In case the fines are supplied as sponge iron fines, the composition of the fines shall be as given above.</li><li>2 1mm fraction should not exceed 30 percent.</li></ul><br><b>Table 3 Chemical Composition of Cold Briquettes (Clause 5.3)</b>\n<table><tr><th>Sl No.</th><th>Constituent</th><th>Grade (A)</th><th>Grade (B)</th><th>Grade (C)</th></tr>\n<tr><td>i)</td><td>Total iron</td><td>88 and above</td><td>87, Min</td><td>85-87</td></tr>\n<tr><td>ii)</td><td>Metallization</td><td>90 ± 2</td><td>85, Min</td><td>82, Min</td></tr>\n<tr><td>iii)</td><td>Metallic iron</td><td>78, Min</td><td>76, Min</td><td>70, Min</td></tr>\n<tr><td>iv)</td><td>Carbon content: a) Coal based, Min</td><td>0.08</td><td>0.08</td><td>0.08</td></tr>\n<tr><td></td><td>b) Gas based</td><td>1.3, Min</td><td>1.3, Min</td><td>1.3, Min</td></tr>\n<tr><td>v)</td><td>S, Max</td><td>0.04</td><td>0.04</td><td>0.04</td></tr>\n<tr><td>vi)</td><td>P, Max</td><td>0.06</td><td>0.06</td><td>0.06</td></tr>\n<tr><td>vii)</td><td>Gangue, Max (SiO2 + Al2O3)</td><td>8</td><td>9</td><td>10</td></tr>\n<tr><td>viii)</td><td>Combined total of Pb, Zn, Cu, Sn, Cr, Ni, etc Max</td><td>0.015</td><td>0.015</td><td>0.015</td></tr></table><br><b>6.1 Size range of sponge iron lumps for steel making</b>\n<table><tr><th>Size</th><th>Requirement</th></tr>\n<tr><td>Size</td><td>4 to 20 mm</td></tr>\n<tr><td>+ 20 mm</td><td>5 percent, Max</td></tr>\n<tr><td>– 4 mm</td><td>5 percent, Max</td></tr></table>\nThis size range shall be valid for sponge iron at the despatch end only. The size range at the receiving point shall depend on the transport and handling during transit. Over and above, sponge iron may be obtained a maximum of 1 percent non-metallics which will neither be considered in the size distribution nor in the chemical analysis of sponge iron.<br>\n<b>3.11 Fines</b> — generally of size 0-4 mm.<br>\n<b>6.2 HBI</b> — Shape: Pillow; Nominal size, mm: 30 × 60 × 110 or 30 × 60 × 90.<br>\n<b>6.3 Cold Briquettes</b> — Shape: Pillow; Nominal size, mm: 64 × 30 × 20 or 38 × 44 × 19.<br>\n<b>7 Density</b> (sponge iron/DRI tested as per IS 14719)\n<table><tr><th>Material</th><th>Bulk Density, g/cc</th><th>Apparent Density, g/cc</th></tr>\n<tr><td>Sponge iron/DRI</td><td>1.8, Min</td><td>—</td></tr>\n<tr><td>HBI</td><td>2.4, Min</td><td>5.0, Min</td></tr>\n<tr><td>Cold briquettes</td><td>2.2, Min</td><td>5–5.5</td></tr></table>\n<b>10.2</b> During transportation of HBI and cold briquettes, the under size (below 5 mm) shall not be more than 5 percent.<br>\n<b>5.5</b> Metallic iron by ferric chloride method (Annex A); a correction factor of + 0.8 percent metallization may be added by the manufacturer in arriving at the actual degree of metallization certified. In case of any dispute the purchaser shall only accept the bromine methanol method (Annex B) result (no correction factor need be added). Carbon by IS 228 (Part 1).<br>\n<b>8.1.3</b> The magnetic portion shall only be considered for the purpose of chemical analysis.", "keywords": "sampling sample preparation sponge iron dri increment metallic iron fe(m) fem ferric chloride sponge iron dri metallic iron fe(m) fem bromine methanol referee sponge iron dri size screen sieve screening undersize oversize fines sponge iron dri"}, {"id": "is1493_1", "no": "IS 1493 (Part 1) : 2025", "title": "Methods of Chemical Analysis of Iron Ores — Part 1 Determination of Common Constituents (Second Revision)", "cat": "Raw material", "facts": ["Cl. 1: Prescribes determination of moisture, silica, total iron, acid soluble iron, aluminium, phosphorous (for > 0.05 percent) and sulphur in iron ores, natural and processed, concentrates and agglomerates, such as pellets and sinters. Sponge iron is not named in the scope; IS 15774 : 2018 B-1.4.1 refers to it for total iron in Fe(M) bromine-methanol method.", "Published November 2025 (MTD 34); first published 1959, revised 1981; this is the second revision. No amendments in the copy.", "Cl. 3.1: Sampling as per IS 1405, IS 9101 and IS 11607; Cl. 3.2.2: pulverize to pass 150 micron, dry at 105 °C ± 5 °C for about 2 h.", "Cl. 8.4: Main solution = 2.000 g sample, silica-free, made up to 250 ml; 50 ml aliquot = 0.4 g.", "Cl. 9.1/9.3: Total iron by stannous chloride reduction, HgCl2, titration with 0.1N K2Cr2O7 (4.903 g/l), diphenylamine sulphonate indicator. Alternative methods: silver reductor (9.4, Annex D) and titanium (III) chloride reduction (9.5).", "Cl. 9.1.1: Applicable to total iron 30 percent to 72 percent; 1 percent to 30 percent can also be determined.", "Cl. 9.7: Total iron, percent = (V1 − V2)[1 − (t2 − t1) × 0.000 2] × A × 0.055 847 × 100 × K / B; blank V2 = V0 − 1.0 (9.6).", "Cl. 9.8: Repeatability r = 0.235; between laboratories R = 0.530. Cl. 9.9 / Annex B: duplicates accepted per flow sheet; reported to two decimal places.", "Cl. 9.10: Natural basis Fe = (100 − moisture percent) × Fe dry / 100 (moisture per IS 11690). Cl. 9.11: Fe × 1.430 = Fe2O3; Fe(II) × 1.286 = FeO; Fe × 1.382 = Fe3O4.", "Annex C: mercury removal from waste solutions before discharge.", "Cl. 8 Silica, gravimetric (silica ≥ 0.5 percent): 2.000 g, HCl + few drops HNO3, bake 1 h at about 120 °C, ignite 1 050 °C about 30 min, HF volatilization; silica, percent = (A − B)/C × 100; r = 0.0511 + 0.0090 × Si percent, R = 0.0831 + 0.0095 × Si percent (8.6); Si = SiO2 × 0.4672 (8.7). Ores with TiO2 ≥ 2 percent: H2SO4 fuming and KHSO4 fusion (8.3.3).", "Lab SOP / WI (SOP/WI tab): DM/QA/WI/11, DM/QA/WI/13, DM/QA/WI/14, DM/QA/WI/15, DM/QA/WI/16, DM/QA/WI/21, DM/QA/WI/22"], "scope": "Total iron — iron ore / sponge iron (for Fe(M) bromine-methanol method)", "follow": "<b>Total iron — key requirements (Clause 9)</b><table><tr><th>Item</th><th>Requirement</th></tr><tr><td>Range (9.1.1)</td><td>30 to 72 percent; 1 to 30 percent can also be determined</td></tr><tr><td>Aliquot (9.3.1)</td><td>50 ml of main solution (0.4 g)</td></tr><tr><td>Titrant (9.2.9)</td><td>K2Cr2O7 0.1N, 4.903 g/l</td></tr><tr><td>Repeatability r (9.8.1)</td><td>0.235</td></tr><tr><td>Reproducibility R (9.8.2)</td><td>0.530</td></tr><tr><td>Reporting (9.9)</td><td>Calculated to 4th decimal, rounded to 2nd decimal</td></tr></table>", "keywords": "metallic iron fe(m) fem bromine methanol referee sponge iron dri total iron fe(t) fe total iron ore sponge dichromate stannous chloride"}, {"id": "is1493", "no": "IS 1493 : 1959", "title": "Methods of Chemical Analysis of Iron Ores (Reaffirmed 2021)", "cat": "Raw material", "facts": ["Cl. 1.1: Methods for moisture, silica, iron, alumina, titanium, manganese, calcium oxide, magnesium oxide, phosphorus, sulphur, ferrous oxide, vanadium and combined water; lead, copper, zinc and arsenic for export purposes.", "Adopted 14 September 1959; Reaffirmed 2001, 2016 and 2021 (copy: Fifth Reprint October 1996).", "Cl. 2.2.2: Laboratory sample pulverized in an agate mortar, dried in an air oven at 105 °C to 110 °C to constant weight, cooled in a desiccator; portions weighed as quickly as possible.", "Cl. 4.2: Results on the sample dried at 105 °C to 110 °C; ferrous oxide reported to the second decimal place. Cl. 4.3: all determinations in duplicate. Cl. 4.4: check analysis on a certified sample.", "Cl. 7.2.9: Standard potassium permanganate 0.1 N = 3.15 g per litre, kept 5 to 6 days in an amber glass-stoppered bottle, filtered through glass wool, standardized against sodium oxalate (AR).", "Cl. 19: Ferrous oxide by the permanganate method (not applicable to high titanium or vanadiferrous ores): about 0.5 g in a platinum crucible, 15 ml H2SO4 (1 : 1), CO2 atmosphere (Fig. 1), boil gently about 5 min, about 5 ml HF, boil gently about 10 min, plunge into about 200 ml boiled and cooled water + 10 ml H2SO4 (1 : 1) + 20 ml boric acid, titrate at once with KMnO4 to a persistent pink colour.", "Cl. 19.5: Ferrous oxide, percent = A × B × 0.071 85 × 100 / C (A = ml KMnO4, B = normality, C = g sample).", "Ferrous oxide is not in the scope of IS 1493 (Part 1) : 2025 (moisture, silica, total iron, acid soluble iron, aluminium, phosphorus > 0.05 percent, sulphur)."], "scope": "Ferrous oxide (FeO) — iron ore / sponge iron", "follow": "<b>Ferrous oxide — key requirements (Clause 19)</b><table><tr><th>Item</th><th>Requirement</th></tr><tr><td>Sample (19.4.1)</td><td>About 0.5 g, dried at 105 °C to 110 °C</td></tr><tr><td>Attack (19.4.1)</td><td>15 ml H2SO4 (1 : 1), boil about 5 min in CO2; about 5 ml HF, boil about 10 min</td></tr><tr><td>Titration medium (19.4.1)</td><td>About 200 ml boiled and cooled water + 10 ml H2SO4 (1 : 1) + 20 ml boric acid</td></tr><tr><td>Titrant (19.3.5, 7.2.9)</td><td>KMnO4 0.1 N (3.15 g/l), standardized against sodium oxalate</td></tr><tr><td>End point</td><td>Persistent pink colour</td></tr><tr><td>Calculation (19.5)</td><td>FeO, percent = A × B × 0.071 85 × 100 / C</td></tr><tr><td>Reporting (4.2)</td><td>Second decimal place, dried basis</td></tr><tr><td>Not applicable</td><td>High titanium or vanadiferrous ores</td></tr></table>", "keywords": "ferrous oxide feo fe(ii) ferrous iron permanganate iron ore sponge iron dri hydrofluoric boric acid carbon dioxide"}, {"id": "iso9035", "no": "ISO 9035 : 1989", "title": "Iron Ores — Determination of Acid-Soluble Iron(II) Content — Titrimetric Method", "cat": "Raw material", "facts": ["Cl. 1: Natural and processed iron ores with 1 percent to 25 percent acid-soluble iron(II) and only traces of metallic iron; for use with the reducibility tests ISO 4695 / ISO 7215. Not applicable above 0.3 percent sulphur as sulphide or 5 percent free carbon.", "Cl. 3: Dissolution in hydrochloric acid in an inert atmosphere; sulphuric–phosphoric acid mixture; titration with potassium dichromate, sodium diphenylaminesulphonate indicator.", "Cl. 4.7: K2Cr2O7 0.016 67 mol/l = 4.904 g per litre at 20 °C. Cl. 4.5: acid mixture 150 ml H2SO4 + 150 ml H3PO4 in 300 ml water, to 1 000 ml.", "Cl. 5.2: Göckel safety trap, or slit rubber valve (Bunsen valve), or inert gas feed tube.", "Cl. 6: Minus 100 micron (160 micron for high combined water / oxidizable compounds); dried at 105 °C ± 2 °C (ISO 7764).", "Cl. 7.3–7.5: About 0.5 g; 1 g to 2 g NaHCO3 / Na2CO3 + 30 ml HCl (few drops HF if SiO2 ≥ 5 percent); close with the trap; about 90 °C, not over 60 min (normally 30 min); 30 ml acid mixture, dilute to about 300 ml, 5 to 6 drops indicator; titrate at once, green → bluish green → violet.", "Cl. 8.1: Fe(II), percent = V × 0.558 5 / m; temperature correction 0.02 percent per °C if more than 2 °C difference.", "Cl. 8.2.1: r = 0.015 3 X + 0.060 0; P = 0.021 5 X + 0.180 6. Annex A: duplicates; 4 determinations if outside r (mean if range < 1.3 r, else median). Cl. 8.2.3: one decimal place.", "Confirmed by ISO in 2025; a revision (ISO/CD 9035) is under development.", "Lab SOP / WI (SOP/WI tab): DM/QA/WI/21 (used for slag), DM/QA/WI/22 (lab method, same principle)"], "scope": "Iron(II) / FeO — iron ore (lab WI uses it for slag)", "follow": "<b>Iron(II) — key requirements</b><table><tr><th>Item</th><th>Requirement</th></tr><tr><td>Range (1)</td><td>1 to 25 percent Fe(II); traces of metallic iron only</td></tr><tr><td>Not applicable (1)</td><td>Sulphide S &gt; 0.3 percent, free C &gt; 5 percent</td></tr><tr><td>Test portion (7.3)</td><td>About 0.5 g, to 0.000 2 g</td></tr><tr><td>Decomposition (7.4)</td><td>1–2 g NaHCO3 + 30 ml HCl, closed (Göckel trap / Bunsen valve), about 90 °C, ≤ 60 min</td></tr><tr><td>Titrant (4.7)</td><td>K2Cr2O7 0.016 67 mol/l</td></tr><tr><td>Calculation (8.1)</td><td>Fe(II) % = V × 0.558 5 / m; FeO = Fe(II) × 1.286</td></tr><tr><td>Repeatability (8.2.1)</td><td>r = 0.015 3 X + 0.060 0</td></tr><tr><td>Reporting (8.2.3)</td><td>One decimal place</td></tr></table>", "keywords": "iron(ii) fe(ii) ferrous iron ferrous oxide feo slag iron ore dichromate hydrochloric acid inert atmosphere gockel bunsen valve"}, {"id": "is15403", "no": "IS 15403 : 2003", "title": "Method for Determination of Sulphur Present in Sponge Iron after Separation of Non-Magnetic Materials", "cat": "Raw material", "facts": ["Cl. 1: Prescribes methods for analyzing sulphur in sponge iron after separation of non-magnetic material.", "Published September 2003; Reaffirmed 2005, 2006, 2007, 2008, 2009, 2010, 2011, 2012, 2017, 2022 (as stamped on copy); no amendments listed.", "Cl. 4: Sample drawn as specified in IS 10812 for chemical analysis.", "Cl. 5: Two methods — a) Evolution and titration method, b) Combustion method; no referee method stated.", "Cl. 5.2: Evolution method — 5 g sample, H2S absorbed in ammonical CdCl2, iodine/thiosulphate titration; Sulphur (percent) = V × 0.01 (on 5 g sample) (5.2.2).", "Cl. 5.4: Combustion method — 1 g sample with tin shots, 1 200 °C, dried O2 1 to 3 l/min, SO2 into AgNO3, NaOH titration; calibrated with 1 g standard sample; S, percent = A × B / C (5.5).", "Range of applicability and precision not stated in the IS.", "Lab SOP / WI (SOP/WI tab): DM/QA/WI/06, DM/QA/WI/07, DM/QA/WI/08 (combustion step only; KIO3 titration is a lab method), DM/QA/WI/17, DM/QA/WI/18"], "scope": "Sulphur (S) of Sponge Iron", "follow": null, "keywords": "sulphur sulfur s% steel evolution combustion billet tmt sulphur sulfur s% sponge iron dri evolution combustion"}, {"id": "is13885", "no": "IS 13885 : 2001", "title": "Non-Magnetic/Char in Sponge Iron (DRI) — Methods of Determination (First Revision)", "cat": "Raw material", "facts": ["Cl. 1 (as substituted by Amendment No. 1, July 2010): methods for determination of non-magnetics/char in truck load of sponge iron, in sponge iron stack and sponge iron packed in bags.", "Published October 2001 (MTD 30); Reaffirmed 2012, 2017, 2022 (as stamped). Amendment No. 1 (July 2010) and Amendment No. 2 (July 2016) seen in the copy.", "Cl. 3: Weighing device 50 kg; sampling scoop 8 kg; hand magnet 100 × 150 mm with handle and detachable plate; sample container. Hand magnet typical intensity 950 to 1 000 gauss (Amd 1).", "Cl. 4.1.1: Truck sample by random sampling per IS 1405, not less than 20 kg out of 10 tons. Cl. 4.2.2: reduce by coning and quartering to 20 kg (Amd 1, was 10 kg).", "Cl. 4.3: % non-magnetics from sample = Y/Z × 100 (1); left over = Y1/Z1 × 100 (2); Total, 1+2 = (Y + Y1)/(Z + Z1) × 100 (as substituted by Amendment No. 2, 2016).", "Cl. 5.1: Stack height 1 250 mm (Amd 1, was 750 mm), up to 25 tons per lot, five holes, min 2 scoops per hole plus random side samples. Cl. 5.3: % = Y/Z × 100.", "Cl. 6 (Amd 1): bags — random bags per table (20 to 120 bags, 2 increments of min 1 kg per bag); % = Y/Z × 100.", "Cl. 7 (Amd 1): moving conveyors — 25 kg sample at discharge end in two or three increments; procedure and calculation as per 6.2/6.3.", "No limit for non-magnetics is specified in this standard.", "Lab SOP / WI (SOP/WI tab): DM/QA/WI/08, DM/QA/WI/17, DM/QA/WI/18, DM/QA/WI/19"], "scope": "Non-magnetic / char in sponge iron", "follow": "<b>Sampling of sponge iron packed in bags (Clause 6.1, Amendment No. 1)</b><table><tr><th>Bag lot in Nos.</th><th>No. of bags sampled on random basis</th><th>No. of increments from each bag</th><th>Minimum mass of each increment</th></tr><tr><td>Up to 200</td><td>20</td><td>2</td><td>1 kg</td></tr><tr><td>200-1 000</td><td>40</td><td>2</td><td>1 kg</td></tr><tr><td>1 000-5 000</td><td>60</td><td>2</td><td>1 kg</td></tr><tr><td>5 000-10 000</td><td>80</td><td>2</td><td>1 kg</td></tr><tr><td>10 000-25 000</td><td>100</td><td>2</td><td>1 kg</td></tr><tr><td>25 000-0 000</td><td>120</td><td>2</td><td>1 kg</td></tr></table>", "keywords": "sulphur sulfur s% sponge iron dri evolution combustion non magnetic char sponge iron dri magnet"}, {"id": "is1607", "no": "IS 1607 : 2013", "title": "Methods of Test Sieving (Second Revision)", "cat": "Mechanical / Physical", "facts": ["Reaffirmed 2018 (as seen on copy); aligned with ISO 2591-1 : 1988; first published 1960, revised 1977. No amendments listed in the copy.", "Cl. 1: general principles for apparatus, procedure and presentation of results; applies to test sieves of woven wire cloth or perforated metal plate.", "Cl. 6.1: test sieves shall comply with relevant part of IS 460; lid and receiver pan where appropriate; Cl. 6.2: do not heat sieves above 80 °C.", "Cl. 7.1.2: reference method always includes final hand sieving; if machine sieving alone is used, state machine and method in report.", "Cl. 7.1.4: weigh charge and fractions to better than 0.1 percent of charge mass.", "Cl. 7.1.6 / Table 1: charge quantity for 200 mm round sieve; residue volume not to exceed col 4.", "Cl. 7.1.7: largest particle should not exceed 10 w<sup>0.7</sup> mm (w = aperture, mm).", "Cl. 7.2.4: 25 mm to 4 mm tested on individual sieves; hand movement about 120 times/min, amplitude about 70 mm.", "Cl. 7.2.5.2: incline about 20°, tap about 120 times/min; after 30 taps turn 90° and give a hard tap.", "Cl. 7.2.7: end point when passing in 1 min is less than 0.1 percent of charge mass (non-friable materials).", "Cl. 7.5.1: sum of fraction masses should not differ by more than -2 percent from charge mass; percentages on sum of fractions, losses recorded separately.", "Cl. 7.5.3: reproducibility to be specified in the relevant product standard.", "IS 15774 : 2018 Cl. 8.1.2 calls IS 1607 for screen analysis of sponge iron.", "Lab SOP / WI (SOP/WI tab): DM/QA/WI/20"], "scope": "Screening test of Sponge Iron", "follow": "<b>Sponge iron size range (IS 15774 : 2018, Cl. 6.1)</b><table><tr><th>Size</th><th>Requirement</th></tr><tr><td>4 to 20 mm</td><td>Size range</td></tr><tr><td>+ 20 mm</td><td>5 percent, Max</td></tr><tr><td>- 4 mm</td><td>5 percent, Max</td></tr></table>Valid at despatch end only; max 1 percent non-metallics not considered in size distribution.<br><b>IS 1607 Table 1 Guide to quantity on 200 mm round sieve</b><table><tr><th>Aperture, w</th><th>Approx. volume of charge, cm3</th><th>Max volume of residue, cm3</th></tr><tr><td>22.4 mm</td><td>1 600</td><td>800</td></tr><tr><td>16 mm</td><td>1 000</td><td>500</td></tr><tr><td>11.2 mm</td><td>800</td><td>400</td></tr><tr><td>8 mm</td><td>500</td><td>250</td></tr><tr><td>5.6 mm</td><td>400</td><td>200</td></tr><tr><td>4 mm</td><td>350</td><td>175</td></tr><tr><td>2.8 mm</td><td>240</td><td>120</td></tr><tr><td>2 mm</td><td>200</td><td>100</td></tr><tr><td>1.4 mm</td><td>160</td><td>80</td></tr><tr><td>1 mm</td><td>140</td><td>70</td></tr><tr><td>710 µm</td><td>120</td><td>60</td></tr><tr><td>500 µm</td><td>100</td><td>50</td></tr><tr><td>355 µm</td><td>30 (as printed)</td><td>40</td></tr><tr><td>250 µm</td><td>70</td><td>35</td></tr><tr><td>180 µm</td><td>60</td><td>30</td></tr><tr><td>125 µm</td><td>50</td><td>25</td></tr><tr><td>90 µm</td><td>42</td><td>21</td></tr><tr><td>63 µm</td><td>35</td><td>17</td></tr><tr><td>45 µm</td><td>30</td><td>15</td></tr><tr><td>32 µm</td><td>26</td><td>13</td></tr></table><b>Key requirements</b><ul><li>End point: passing in 1 min &lt; 0.1 percent of charge mass (7.2.7)</li><li>Weighing accuracy: better than 0.1 percent of charge mass (7.1.4)</li><li>Sum of fractions within -2 percent of charge mass (7.5.1)</li><li>Largest particle &le; 10 w<sup>0.7</sup> mm (7.1.7)</li></ul>", "keywords": "size screen sieve screening undersize oversize fines sponge iron dri"}, {"id": "is1350_1", "no": "IS 1350 (Part 1) : 2025", "title": "Coal and Coke — Methods of Test: Part 1 Proximate Analysis (Third Revision)", "cat": "Raw material", "facts": ["Third Revision, April 2025; Solid Mineral Fuels and Solid Biofuels Sectional Committee, PCD 07; Doc No. PCD 07 (24223). First published 1959; split into 3 parts in 1969; Part 1 revised in 1984.", "Changes in this revision: alternate moisture method by drying in air (three stage) added; title changed to 'Coal and coke — Methods of test: Part 1 Proximate analysis'; Amendment No. 1 to the 1984 version incorporated.", "Other parts: Part 2 gross calorific value; Part 3 total sulphur (Eschka method); Part 4 ultimate analysis (Sec 1 carbon and hydrogen, Sec 2 nitrogen); Part 5 special impurities (carbonate carbon, chlorine and phosphorus).", "Cl. 5: Sampling as per IS 436 (Part 1/Sec 1) for coal and IS 16143 (Part 5) for coke. Sample about 300 g ground to pass 212 micron IS sieve; at the laboratory re-sieve, air-dry 24 h, mix and bottle (5.2.3); irregular results: grind to 125 micron (5.2.4).", "Cl. 7.2.1 Indirect moisture methods: Annex A one stage (Method I at 200 °C, coke only; Method II at (108 ± 2) °C, about 1.5 g of 212 micron sample); Annex B two stage (air-drying + oven-drying); Annex C three stage (air-drying + oven at (38 ± 2) °C + oven at (108 ± 2) °C); Annex D minimum free-space oven at (200 ± 5) °C in nitrogen (coke). Cl. 7.2.2 Direct method: Annex E gravimetric, nitrogen stream and absorption tubes.", "Cl. 7.2.3: moisture at 60 percent RH and 40 °C (reference and rapid methods); 7.2.4: moisture at 96 percent RH and 40 °C (saturated potassium sulphate, 48 h); 7.2.5: free water = A − [(100 − A) × B / (100 − B)].", "Cl. 8 Volatile matter: 1.00 g to 1.01 g air-dried sample, (900 ± 10) °C for exactly 7 min in a silica crucible with lid (10 g to 14 g, lid clearance max 0.5 mm); V = 100 (M2 − M3)/(M2 − M1) − M0.", "Cl. 9 Ash: about 1 g to 2 g, 500 °C in 30 min, (815 ± 10) °C in a further 30 min to 60 min, hold 60 min; (850 ± 10) °C for coals with more than 4 percent CO2; re-ignite to less than 0.001 g change.", "Cl. 10: F = 100 − (M0 + A + V); reporting on air-dried, 60 percent RH and 40 °C, dry and dry mineral free bases; mineral matter = 1.1 A for most Indian coals (10.6.1); report form in 10.7.", "Rounding off as per IS 2 : 2022.", "Lab SOP / WI (SOP/WI tab): DM/QA/WI/23, DM/QA/WI/24, DM/QA/WI/25, DM/QA/WI/26, DM/QA/WI/27, DM/QA/WI/28"], "scope": "Coal — proximate analysis (moisture, total moisture, volatile matter, ash, fixed carbon)", "follow": "<b>Precision (duplicate determinations)</b><table><tr><th>Test</th><th>Range</th><th>Repeatability</th><th>Reproducibility</th></tr><tr><td>Volatile matter (8.2.6)</td><td>Coal</td><td>1.0 percent of the arithmetic mean</td><td>1.5 percent of the arithmetic mean</td></tr><tr><td>Volatile matter (8.2.6)</td><td>Coke</td><td>0.2 units</td><td>0.4 units</td></tr><tr><td>Ash (9.5)</td><td>Up to 10.0 percent</td><td>0.2 units</td><td>0.4 units</td></tr><tr><td>Ash (9.5)</td><td>Over 10.0 percent</td><td>2.0 percent of the arithmetic mean</td><td>3.0 percent of the arithmetic mean</td></tr><tr><td>Moisture, direct method (E-5)</td><td>Up to 3.0 percent</td><td>0.1 units</td><td>0.2 units</td></tr><tr><td>Moisture, direct method (E-5)</td><td>Over 3.0 percent</td><td>3.0 percent of the arithmetic mean</td><td>6.0 percent of the arithmetic mean</td></tr></table>", "keywords": "coal coke proximate analysis moisture total moisture volatile matter ash fixed carbon is 1350"}, {"id": "is1608", "no": "IS 1608 (Part 1) : 2022", "title": "Metallic materials — Tensile testing — Part 1: Method of test at room temperature", "cat": "Mechanical / Physical", "facts": ["Identical to ISO 6892-1 : 2019", "Testing machine verification is referred to IS 1828 (Part 1) (tension/compression machines — force measuring system)", "Part 2 = elevated temperature, Part 3 = low temperature", "Only tells HOW to test; the pass/fail values come from the product standard (e.g. IS 1786)"], "scope": "TMT Bars: % Elongation, 0.2% Proof Stress, Total Elongation at maximum force, Ultimate Tensile Strength, Yield Stress", "follow": null}, {"id": "is1599", "no": "IS 1599 : 2023", "title": "Metallic materials — Bend test (Fifth Revision)", "cat": "Mechanical / Physical", "facts": ["Identical to ISO 7438 : 2020", "Checks the ability of the metal to undergo plastic deformation in bending", "Applies to test pieces taken as per the relevant product standard", "Not for tubes in full section or welded joints (other standards exist for those)"], "scope": "TMT Bars: Bend test (mandrel dia 24 to 200 mm in the scope list)", "follow": null}, {"id": "is1786", "no": "IS 1786 : 2008", "title": "High strength deformed steel bars and wires for concrete reinforcement — Specification (Fourth Revision)", "cat": "Product", "facts": ["Grades (after Amendment 3, March 2017): Fe 415, Fe 415D, Fe 415S, Fe 500, Fe 500D, Fe 500S, Fe 550, Fe 550D, Fe 600, Fe 650, Fe 700", "The number after Fe = specified minimum 0.2% proof stress / yield stress in N/mm²", "Applies to hot-rolled steel, hot-rolled with controlled cooling and tempering (TMT), and cold-worked steel; also bars in coils and coated bars", "Chemical analysis: IS 228 (relevant parts) or any other established instrumental / chemical method", "Nitrogen should not exceed 0.012 % (120 ppm) — Amendment 3 note", "TS/YS ratio = tensile strength ÷ actual yield / 0.2% proof stress of the test piece"], "scope": "TMT Bars: Mass per metre, Re-bend test, TS/YS ratio (tensile values tested per IS 1608, bend per IS 1599)", "follow": "Grade-wise C, S, P, S+P and Carbon Equivalent limits: Table in Cl. 4.2 (as amended) — exact values <b>NOT FOUND</b> here (check the BIS copy before use)"}, {"id": "iso17025", "no": "ISO/IEC 17025 : 2017", "title": "General requirements for the competence of testing and calibration laboratories (Third edition, 2017-11)", "cat": "Lab / System", "facts": ["Accreditation standard used by NABL for the lab scope", "Clause layout: 4 General (impartiality, confidentiality) · 5 Structural · 6 Resource · 7 Process · 8 Management system; Annex A metrological traceability, Annex B management system options", "Cl. 8.1: management system by Option A (cl. 8.2 to 8.9) or Option B (a system as per ISO 9001 that also supports cl. 4 to 7)", "Cl. 7.2.1.5: verify a standard method before introducing it (keep verification records; repeat if the method is revised)", "Cl. 7.2.2.1: validate non-standard / lab-developed methods and standard methods used outside their intended scope or modified (e.g. DM/QA/WI/06 and WI/07: IS 15403 sponge-iron method used for steel)", "Cl. 7.6.3: testing labs shall evaluate measurement uncertainty (estimate allowed where rigorous evaluation is not possible)", "Cl. 7.7.2: compare performance with other labs — proficiency testing and/or interlaboratory comparison", "Cl. 8.5 Note: no formal risk-management method is required; actions must be proportional to the impact on validity of results"], "scope": "Basis of the NABL accreditation itself — lab quality system, competence and reporting", "keywords": "17025 nabl accreditation quality system impartiality confidentiality competence training authorization equipment calibration traceability crm reference material method verification validation measurement uncertainty proficiency testing ilc control chart test report decision rule complaint nonconforming work corrective action internal audit management review risk records document control", "follow": "<b>Key requirements (summary in own words — read the standard for exact wording):</b><table style='width:100%;font-size:12px;border-collapse:collapse;margin:4px 0'><tr><th style='text-align:left'>Clause</th><th style='text-align:left'>What the lab must do</th></tr><tr><td>4.1</td><td>Work impartially; identify risks to impartiality on an ongoing basis and show how they are removed or minimised</td></tr><tr><td>4.2</td><td>Keep customer information confidential (legally enforceable commitment); inform the customer before placing information in public domain</td></tr><tr><td>5</td><td>Legal entity; defined management; documented range of lab activities; organisation chart, responsibilities and authorities; personnel to run and report on the management system</td></tr><tr><td>6.2</td><td>Documented competence requirements per function; procedures + records for selection, training, supervision, authorisation and monitoring competence; authorise staff for method work, result analysis and report authorisation</td></tr><tr><td>6.3</td><td>Suitable facilities; document environmental needs; monitor, control and record conditions where they affect results; control access and separate incompatible activities</td></tr><tr><td>6.4</td><td>Equipment procedure (handling, storage, maintenance); verify before use; calibration programme; calibration status label; take faulty equipment out of service and assess its effect (7.10); intermediate checks by procedure; update correction factors; equipment records (6.4.13 a–h: identity incl. software, maker/serial, verification, location, calibration dates/results/due date, reference materials, maintenance, damage/repair)</td></tr><tr><td>6.5</td><td>Metrological traceability to SI via competent calibration lab, CRM from competent producer (ISO 17034), or direct realisation; otherwise to an appropriate reference</td></tr><tr><td>6.6</td><td>Procedure + records for purchased products/services (CRMs, calibration, PT etc.): requirements, supplier evaluation/re-evaluation, checking before use</td></tr><tr><td>7.1</td><td>Review requests/contracts (simplified for internal customers); agree the decision rule when a pass/fail statement is asked</td></tr><tr><td>7.2</td><td>Use the latest valid method; verify standard methods (7.2.1.5); deviations only if documented, justified, authorised and accepted; validate non-standard/modified methods and keep validation records (7.2.2.4)</td></tr><tr><td>7.3</td><td>Sampling plan and method; sampling records (method, date/time, sample id, person, equipment, conditions, location, deviations)</td></tr><tr><td>7.4</td><td>Item handling procedure; unique identification of samples; record deviations on receipt</td></tr><tr><td>7.5</td><td>Technical records enough to repeat the test; date and identity of analyst and checker; record observations at the time; track amendments (keep original and changed data)</td></tr><tr><td>7.6</td><td>Identify contributions and evaluate measurement uncertainty for tests</td></tr><tr><td>7.7</td><td>Procedure to monitor validity of results (e.g. CRMs/QC materials, control charts, replicate tests, retesting retained items, intralab comparison, blind samples); record so trends are seen; take action if outside criteria; PT / interlaboratory comparison</td></tr><tr><td>7.8</td><td>Review and authorise results before release; report contents per 7.8.2.1 a–p (title, lab name/address, unique id, customer, method, item, dates, results with units, deviations, authoriser, etc.); uncertainty when relevant; decision rule for conformity statements; amendments as a separate identified document</td></tr><tr><td>7.9</td><td>Documented complaint process; outcome reviewed by person not involved in the original work</td></tr><tr><td>7.10</td><td>Nonconforming work procedure: evaluate impact on previous results, recall work / notify customer if needed, records, corrective action if it can recur</td></tr><tr><td>7.11</td><td>Validate the lab information management system (computerised or manual) before use and after changes; protect from unauthorised access, tampering and loss; check calculations and data transfers</td></tr><tr><td>8.2–8.4</td><td>Policies and objectives; document control (approval, review, revision status, unique id, obsolete documents controlled); record control and retention</td></tr><tr><td>8.5–8.7</td><td>Risks and opportunities; improvement and customer feedback; corrective action with root cause and effectiveness review</td></tr><tr><td>8.8</td><td>Internal audits at planned intervals (audit programme, criteria, scope, records)</td></tr><tr><td>8.9</td><td>Management review at planned intervals — inputs 8.9.2 a–o (incl. audits, PT/validity results, complaints, feedback, resources, risks, training); outputs and decisions recorded</td></tr></table>"}];
function renderIndStandards() {
  const box = document.getElementById("stdList");
  const q = (document.getElementById("stdSearch").value || "").trim().toLowerCase();
  let notes = {};
  try { notes = JSON.parse(localStorage.getItem("indStdNotes") || "{}"); } catch (e) { notes = {}; }
  const esc = (t) => String(t).replace(/[&<>]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" }[c]));
  const list = IND_STANDARDS.filter(x => !q || (x.no + " " + x.title + " " + x.scope + " " + x.cat + " " + (x.keywords || "") + " " + x.facts.join(" ")).toLowerCase().includes(q));
  box.innerHTML = list.length ? list.map(x => `
    <details class="stdItem" data-id="${x.id}">
      <summary><span class="stdNo">${esc(x.no)}</span><span class="stdTitle">${esc(x.title)}</span></summary>
      <div class="stdBody">
        <span class="stdCat">${esc(x.cat)}</span>
        <h4>Used for (NABL scope)</h4>
        <div>${esc(x.scope)}</div>
        <h4>Key points</h4>
        <ul>${x.facts.map(f => `<li>${esc(f)}</li>`).join("")}</ul>
        <h4>Limits / clauses to follow</h4>
        <div>${x.follow || "Detailed clauses and limits: <b>NOT FOUND</b> (not verified from the BIS text) — add them below from your copy."}</div>
        <h4>My notes</h4>
        <textarea class="stdNote" data-id="${x.id}" placeholder="Write clauses, limits, sample size etc.">${esc(notes[x.id] || "")}</textarea>
      </div>
    </details>`).join("") : `<div style="color:var(--muted);font-size:13px;">No standard matches "${esc(q)}".</div>`;
  box.querySelectorAll(".stdNote").forEach(t => t.addEventListener("input", () => {
    let n = {};
    try { n = JSON.parse(localStorage.getItem("indStdNotes") || "{}"); } catch (e) { n = {}; }
    n[t.dataset.id] = t.value;
    localStorage.setItem("indStdNotes", JSON.stringify(n));
  }));
}
document.getElementById("stdSearch").addEventListener("input", renderIndStandards);
renderIndStandards();

